INSERT INTO public.risks (risk_id, quelle, text_de, text_en, primary_control_framework) VALUES
  ('DR-AIACT-A-01.1', 'Delta-Pack', 'Risiko bei Nichterfüllung: Ein Bewertungsmodell, das Personen über Kontextgrenzen hinweg nach Sozialverhalten einstuft (etwa Kundenverhalten, das in Kreditentscheidungen einfließt), erfüllt unbemerkt den Verbotstatbestand des Art. 5 Abs. 1 lit. c, weil niemand den Zusammenhang zwischen Datenquelle und Benachteiligung geprüft hat. Verstöße gegen Art. 5 sind seit 2. Februar 2025 verboten und werden nach Art. 99 Abs. 3 mit bis zu 35 Mio. € oder 7 % des weltweiten Jahresumsatzes geahndet; das System muss sofort abgeschaltet werden, und Betroffene können Schadensersatz geltend machen.', 'Risk of non-compliance: A scoring model that ranks people on social behaviour across unrelated contexts (e.g. customer conduct feeding credit decisions) silently meets the prohibition of Art. 5(1)(c) because nobody examined the link between data source and detrimental treatment. Art. 5 prohibitions have applied since 2 February 2025 and carry fines under Art. 99(3) of up to EUR 35 million or 7 % of global annual turnover; the system must be shut down immediately and affected persons may claim damages.', 'AIACT'),
  ('DR-AIACT-A-01.2', 'Delta-Pack', 'Risiko bei Nichterfüllung: Eine Kameraanalyse mit Gesichtsabgleich am Werkstor oder in Kundenbereichen wird als „Sicherheitstechnik“ beschafft, ohne dass jemand erkennt, dass sie biometrische Fernidentifizierung in Echtzeit in öffentlich zugänglichen Räumen darstellt. Da die Ausnahmen des Art. 5 Abs. 1 lit. h ausschließlich Strafverfolgungsbehörden mit richterlicher Genehmigung offenstehen, liegt für ein privates Unternehmen praktisch immer ein Verbot vor – mit Bußgeld nach Art. 99 Abs. 3 (bis 35 Mio. €/7 %), einem parallelen DSGVO-Verstoß nach Art. 9 und einer öffentlichkeitswirksamen Abschaltungsanordnung.', 'Risk of non-compliance: Camera analytics with face matching at the factory gate or in customer areas gets procured as ''security technology'' without anyone recognising that it constitutes real-time remote biometric identification in publicly accessible spaces. Because the exceptions in Art. 5(1)(h) are reserved for law enforcement with judicial authorisation, a private company is almost always within the prohibition, facing fines under Art. 99(3) (up to EUR 35 million/7 %), a parallel GDPR Art. 9 breach and a highly visible shutdown order.', 'AIACT'),
  ('DR-AIACT-A-01.3', 'Delta-Pack', 'Risiko bei Nichterfüllung: Personalisierungs- und Empfehlungslogiken (Dark Patterns, emotionsbasierte Ansprache, Ausnutzung von Alter, Behinderung oder finanzieller Not) überschreiten schleichend die Grenze zur manipulativen Beeinflussung, ohne dass die Fachabteilung dies als Verbotstatbestand des Art. 5 Abs. 1 lit. a/b erkennt. Wird das nachgewiesen, drohen Bußgeld bis 35 Mio. €/7 % nach Art. 99 Abs. 3, Verbraucherschutzverfahren und die Rückabwicklung der beeinflussten Geschäfte; die Reputation als vertrauenswürdiger Anbieter ist nachhaltig beschädigt.', 'Risk of non-compliance: Personalisation and recommendation logic (dark patterns, emotion-driven nudging, exploitation of age, disability or financial distress) gradually crosses into manipulative influence without the business unit recognising it as a prohibited practice under Art. 5(1)(a)/(b). Once proven, this triggers fines of up to EUR 35 million/7 % under Art. 99(3), consumer protection proceedings and reversal of the influenced transactions; the reputation as a trustworthy provider is lastingly damaged.', 'AIACT'),
  ('DR-AIACT-A-01.4', 'Delta-Pack', 'Risiko bei Nichterfüllung: Ein Risikoscore, der aus Profil- oder Persönlichkeitsmerkmalen die Wahrscheinlichkeit künftiger Straftaten einzelner Personen ableitet (etwa in Betrugs- oder Werkschutzabteilungen), fällt unter das Verbot des Art. 5 Abs. 1 lit. d, sobald er nicht ausschließlich auf objektiven, überprüfbaren Fakten zu einer konkreten Tat beruht. Neben dem Bußgeld nach Art. 99 Abs. 3 (bis 35 Mio. €/7 %) drohen die Unverwertbarkeit aller darauf gestützten Maßnahmen und Diskriminierungsklagen der betroffenen Personen.', 'Risk of non-compliance: A risk score that infers the likelihood of future offences by individuals from profiling or personality traits (for example in fraud or corporate security units) falls under the prohibition of Art. 5(1)(d) as soon as it is not based solely on objective, verifiable facts linked to a specific act. Beyond the fine under Art. 99(3) (up to EUR 35 million/7 %), every measure based on the score becomes unusable and the persons concerned can bring discrimination claims.', 'AIACT'),
  ('DR-AIACT-A-01.5', 'Delta-Pack', 'Risiko bei Nichterfüllung: Ohne unterzeichnete Prüfdokumentation kann das Unternehmen gegenüber der Marktüberwachungsbehörde nicht belegen, dass die Verbotstatbestände überhaupt geprüft wurden; ein späteres Bestreiten wirkt wie eine Schutzbehauptung. Bei einer Untersuchung nach Art. 74 fehlt jede Entlastung, sodass selbst ein Grenzfall als vorsätzlicher Art.-5-Verstoß mit dem Höchstrahmen des Art. 99 Abs. 3 bewertet werden kann; intern fehlt zudem der Beleg, wer die Verantwortung für die Freigabe trug.', 'Risk of non-compliance: Without a signed assessment record the company cannot demonstrate to the market surveillance authority that the prohibited practices were ever examined; a later denial reads as a self-serving claim. In an investigation under Art. 74 there is nothing exculpatory, so even a borderline case can be treated as a deliberate Art. 5 breach at the top of the Art. 99(3) range, and internally there is no evidence of who took responsibility for the release.', 'AIACT'),
  ('DR-AIACT-A-02.1', 'Delta-Pack', 'Risiko bei Nichterfüllung: Ohne schriftliche Klassifizierung wird ein Hochrisiko-System (etwa Bewerber-Screening oder Kreditwürdigkeitsprüfung) als „normales Tool“ betrieben, sodass Art. 9–15, Konformitätsbewertung und Registrierung komplett ausbleiben. Die Behörde wertet das nach Art. 99 Abs. 4 als Anbieter- bzw. Betreiberverstoß mit bis zu 15 Mio. €/3 %; nachträgliche Konformität kostet Monate Nachdokumentation, und das System darf bis dahin nicht eingesetzt werden.', 'Risk of non-compliance: Without a written classification a high-risk system (such as applicant screening or creditworthiness assessment) is run as an ''ordinary tool'', so Art. 9–15, conformity assessment and registration are skipped entirely. The authority treats this as a provider or deployer breach under Art. 99(4) with fines up to EUR 15 million/3 %; achieving conformity afterwards takes months of retroactive documentation, during which the system may not be used.', 'AIACT'),
  ('DR-AIACT-A-02.2', 'Delta-Pack', 'Risiko bei Nichterfüllung: Werden nicht alle acht Anhang-III-Bereiche systematisch abgefragt, bleiben typische Grenzfälle unentdeckt – etwa ein Chatbot, der den Zugang zu wesentlichen Diensten steuert (Nr. 5), oder eine Lernplattform mit Bewertungsfunktion (Nr. 3). Die Folge ist eine unbeabsichtigte Unterklassifizierung; die Beweislast für die Ausnahme nach Art. 6 Abs. 3 trägt der Anbieter, der sie ohne dokumentierte Bereichsprüfung nicht führen kann, und Art. 99 Abs. 4 (bis 15 Mio. €/3 %) greift.', 'Risk of non-compliance: If the eight Annex III areas are not checked systematically, typical borderline cases go unnoticed – a chatbot that gates access to essential services (No. 5), or a learning platform with assessment functions (No. 3). The result is unintended under-classification; the burden of proving the Art. 6(3) exemption lies with the provider, who cannot discharge it without a documented area-by-area review, and Art. 99(4) (up to EUR 15 million/3 %) applies.', 'AIACT'),
  ('DR-AIACT-A-02.3', 'Delta-Pack', 'Risiko bei Nichterfüllung: Erweitert der Betreiber den Verwendungszweck (etwa ein Support-Modell künftig für Personalentscheidungen), wird er nach Art. 25 Abs. 1 selbst zum Anbieter mit allen Pflichten der Art. 16 ff., ohne es zu bemerken. Das System läuft dann ohne Konformitätsbewertung im Hochrisikobereich; die Behörde kann den Rückruf anordnen und nach Art. 99 Abs. 4 Bußgeld bis 15 Mio. €/3 % verhängen, während der ursprüngliche Anbieter für diese Nutzung nicht mehr haftet.', 'Risk of non-compliance: If the deployer extends the intended purpose (e.g. reusing a support model for HR decisions), it becomes a provider itself under Art. 25(1) with all obligations of Art. 16 et seq. without noticing. The system then operates in the high-risk domain without conformity assessment; the authority can order a recall and impose fines up to EUR 15 million/3 % under Art. 99(4), while the original provider is no longer liable for this use.', 'AIACT'),
  ('DR-AIACT-A-02.5', 'Delta-Pack', 'Risiko bei Nichterfüllung: Bleibt eine geänderte Risikoeinstufung intern unkommuniziert, arbeiten Betrieb, Datenschutz und Einkauf mit veralteten Annahmen weiter – Aufsicht, Logging und Nutzerinformation werden nicht nachgezogen, und der Eintrag in der EU-Datenbank nach Art. 49 stimmt nicht mehr. Bei einer Prüfung fällt die Diskrepanz zwischen Registrierung und tatsächlichem Einsatz sofort auf und wird als unrichtige Information gegenüber der Behörde nach Art. 99 Abs. 5 (bis 7,5 Mio. €/1 %) gewertet.', 'Risk of non-compliance: If a changed risk classification is not communicated internally, operations, data protection and procurement keep working on outdated assumptions – oversight, logging and user information are not adjusted, and the EU database entry under Art. 49 no longer matches reality. During an inspection the gap between registration and actual use is immediately visible and is treated as incorrect information supplied to the authority under Art. 99(5) (up to EUR 7.5 million/1 %).', 'AIACT'),
  ('DR-AIACT-A-03.1', 'Delta-Pack', 'Risiko bei Nichterfüllung: Ohne ein dokumentiertes, über den gesamten Lebenszyklus geführtes Risikomanagementsystem fehlt der zentrale Nachweis der Anhang-IV-Dokumentation; die Konformitätsbewertung nach Art. 43 kann nicht bestanden werden, und eine dennoch ausgestellte EU-Konformitätserklärung wäre unwahr. Neu auftretende Risiken nach dem Inverkehrbringen werden nicht erfasst, und die Behörde kann nach Art. 99 Abs. 4 (bis 15 Mio. €/3 %) sanktionieren sowie nach Art. 79 den Marktzugang entziehen.', 'Risk of non-compliance: Without a documented risk management system maintained across the entire lifecycle, the core evidence required by Annex IV is missing; the conformity assessment under Art. 43 cannot be passed, and any EU declaration of conformity issued anyway would be false. Risks emerging after placing on the market are not captured, and the authority can sanction under Art. 99(4) (up to EUR 15 million/3 %) and withdraw market access under Art. 79.', 'AIACT'),
  ('DR-AIACT-A-03.2', 'Delta-Pack', 'Risiko bei Nichterfüllung: Werden nicht alle Risikoarten (Gesundheit, Sicherheit, Grundrechte, Diskriminierung, Fehlfunktion, Missbrauch) systematisch identifiziert, bleiben ganze Schadensklassen ohne Gegenmaßnahme – typischerweise die Grundrechtsrisiken, die technische Teams nicht im Blick haben. Ein späterer Vorfall in einer nicht betrachteten Kategorie gilt als vorhersehbar und unbehandelt, was die Produkthaftung verschärft und das Risikomanagement nach Art. 9 Abs. 2 lit. a als unvollständig disqualifiziert.', 'Risk of non-compliance: If not all risk types (health, safety, fundamental rights, discrimination, malfunction, misuse) are identified systematically, entire classes of harm remain without countermeasures – typically the fundamental-rights risks that technical teams do not have in view. A later incident in an unexamined category counts as foreseeable and untreated, which aggravates product liability and disqualifies the risk management under Art. 9(2)(a) as incomplete.', 'AIACT'),
  ('DR-AIACT-A-03.3', 'Delta-Pack', 'Risiko bei Nichterfüllung: Wird das System nur im Labor mit bereinigten Daten getestet, treten Fehlklassifikationen, Latenzprobleme und Verteilungsverschiebungen erst im Produktivbetrieb bei echten Betroffenen auf. Art. 9 Abs. 6–8 fordert Tests unter realen Bedingungen; fehlen sie, ist die Konformitätsbewertung angreifbar, und Tests außerhalb eines Reallabors ohne die Vorgaben des Art. 60 (Genehmigung, Einwilligung, Registrierung) stellen selbst einen sanktionsbewehrten Verstoß dar.', 'Risk of non-compliance: If the system is tested only in the lab on cleaned data, misclassifications, latency problems and distribution shifts surface only in production, affecting real people. Art. 9(6)–(8) requires testing under real-world conditions; without it the conformity assessment is contestable, and real-world testing outside a sandbox that ignores the Art. 60 requirements (approval, consent, registration) is itself a sanctionable breach.', 'AIACT'),
  ('DR-AIACT-A-03.4', 'Delta-Pack', 'Risiko bei Nichterfüllung: Identifizierte, aber nicht behandelte Risiken bleiben als bekannte Schwachstellen bestehen – ein Bias-Befund ohne Maßnahme wird im Audit zum Beleg bewussten Inkaufnehmens. Art. 9 Abs. 5 verlangt, dass das Restrisiko nach Maßnahmen vertretbar ist; ohne Umsetzungsnachweis ist das nicht belegbar, was die Konformität nach Art. 43 verhindert und bei Schadenseintritt eine Haftung wegen grober Fahrlässigkeit begründet.', 'Risk of non-compliance: Risks that were identified but never treated persist as known weaknesses – a bias finding without a mitigation becomes audit evidence of deliberate acceptance. Art. 9(5) requires the residual risk after measures to be acceptable; without proof of implementation this cannot be shown, which blocks conformity under Art. 43 and, once harm occurs, supports liability for gross negligence.', 'AIACT'),
  ('DR-AIACT-A-03.5', 'Delta-Pack', 'Risiko bei Nichterfüllung: Ohne formale Restrisikoakzeptanz weiß niemand, wer entschieden hat, dass das verbleibende Risiko tragbar ist; im Schadensfall schiebt die Fachabteilung die Verantwortung auf die IT und umgekehrt. Die Marktüberwachung wertet die fehlende Akzeptanz als nicht abgeschlossenes Risikomanagement nach Art. 9 Abs. 5, und die Geschäftsleitung kann sich nicht auf eine informierte Entscheidung berufen – persönliche Organhaftung wird möglich.', 'Risk of non-compliance: Without formal residual-risk acceptance nobody knows who decided that the remaining risk is tolerable; when harm occurs the business unit blames IT and vice versa. Market surveillance treats missing acceptance as an unfinished risk management process under Art. 9(5), and executive management cannot rely on having made an informed decision – personal liability of officers becomes possible.', 'AIACT'),
  ('DR-AIACT-A-03.6', 'Delta-Pack', 'Risiko bei Nichterfüllung: Wird das tatsächliche Fach- und Erfahrungsniveau der Bediener ignoriert, sind Warnhinweise und Aufsichtsmechanismen für Experten ausgelegt, während in der Praxis Sachbearbeiter ohne KI-Kenntnis die Ergebnisse übernehmen. Art. 9 Abs. 5 UAbs. 2 verlangt genau diese Berücksichtigung; ihr Fehlen führt zu Fehlbedienung, unerkanntem Automation Bias und einer Gebrauchsanweisung nach Art. 13, die als unzureichend gilt.', 'Risk of non-compliance: If the actual expertise and experience of operators is ignored, warnings and oversight mechanisms are designed for experts while in practice case workers without AI knowledge adopt the outputs. Art. 9(5) second subparagraph requires precisely this consideration; its absence leads to misuse, undetected automation bias and instructions for use under Art. 13 that are deemed inadequate.', 'AIACT'),
  ('DR-AIACT-A-03.7', 'Delta-Pack', 'Risiko bei Nichterfüllung: Ein Risikomanagement, das nach der Erstbewertung nicht mehr aktualisiert wird, kennt weder neue Angriffsmuster (Prompt Injection, Datenvergiftung) noch Änderungen der Nutzergruppe oder der Rechtslage. Art. 9 Abs. 2 verlangt einen iterativen, regelmäßig aktualisierten Prozess; ein veraltetes RMS entwertet die Nachbetriebsbeobachtung nach Art. 72 und wird bei einer Überprüfung als Nichtkonformität mit Bußgeldfolge nach Art. 99 Abs. 4 gewertet.', 'Risk of non-compliance: A risk management process that is never updated after the initial assessment knows nothing of new attack patterns (prompt injection, data poisoning) or changes in the user population or legal landscape. Art. 9(2) demands an iterative, regularly updated process; an outdated RMS undermines post-market monitoring under Art. 72 and is treated during inspection as non-conformity with fines under Art. 99(4).', 'AIACT'),
  ('DR-AIACT-A-04.1', 'Delta-Pack', 'Risiko bei Nichterfüllung: Ungeprüfte Trainingsdaten reproduzieren historische Benachteiligungen – etwa weniger Einladungen für Bewerberinnen oder schlechtere Scores für bestimmte Postleitzahlen –, und das Modell diskriminiert systematisch, ohne dass es jemand misst. Neben dem Verstoß gegen Art. 10 Abs. 2 lit. f–g (Art. 99 Abs. 4, bis 15 Mio. €/3 %) drohen AGG-Klagen mit Beweislastumkehr und öffentliche Berichterstattung über „diskriminierende KI“.', 'Risk of non-compliance: Unexamined training data reproduces historical disadvantage – fewer interview invitations for women, worse scores for certain postcodes – and the model discriminates systematically without anyone measuring it. Beyond the breach of Art. 10(2)(f)–(g) (Art. 99(4), up to EUR 15 million/3 %), the company faces equal-treatment claims with reversed burden of proof and press coverage about ''discriminatory AI''.', 'AIACT'),
  ('DR-AIACT-A-04.2', 'Delta-Pack', 'Risiko bei Nichterfüllung: Ohne Dokumentation von Herkunft, Umfang und Vorverarbeitung der Daten lässt sich später nicht rekonstruieren, warum das Modell bestimmte Muster gelernt hat, und die Rechtsgrundlagen (DSGVO, Urheberrecht) einzelner Quellen sind nicht nachweisbar. Anhang IV Nr. 2 lit. d verlangt diese Angaben in der technischen Dokumentation; fehlen sie, ist die Dokumentation unvollständig, die Konformitätsbewertung nicht bestehbar und eine Behördenauskunft nach Art. 21 nicht erfüllbar.', 'Risk of non-compliance: Without documentation of data provenance, volume and pre-processing it is impossible to reconstruct later why the model learned certain patterns, and the legal basis (GDPR, copyright) for individual sources cannot be demonstrated. Annex IV No. 2(d) requires these details in the technical documentation; without them the documentation is incomplete, the conformity assessment cannot be passed and information requests under Art. 21 cannot be answered.', 'AIACT'),
  ('DR-AIACT-A-04.3', 'Delta-Pack', 'Risiko bei Nichterfüllung: Ohne definierte und gemessene Qualitätskriterien (Vollständigkeit, Fehlerquote, Aktualität) gelangen fehlerhafte oder veraltete Datensätze unbemerkt ins Training, und die Modellleistung wird auf falscher Grundlage als „gut“ bewertet. Art. 10 Abs. 3 fordert relevante, hinreichend repräsentative und möglichst fehlerfreie Datensätze; ohne Messung ist diese Anforderung nicht belegbar, und die Genauigkeitsangaben nach Art. 15 verlieren ihre Grundlage.', 'Risk of non-compliance: Without defined and measured quality criteria (completeness, error rate, currency), flawed or stale datasets enter training unnoticed and model performance is rated ''good'' on a false basis. Art. 10(3) requires datasets that are relevant, sufficiently representative and as free of errors as possible; without measurement this cannot be evidenced, and the accuracy statements under Art. 15 lose their foundation.', 'AIACT'),
  ('DR-AIACT-A-04.4', 'Delta-Pack', 'Risiko bei Nichterfüllung: Fehlen Untergruppen (ältere Menschen, Dialektsprecher, seltene Krankheitsbilder) im Trainingsdatensatz, versagt das Modell genau bei diesen Personen mit deutlich höherer Fehlerrate – in der Gesamtmetrik unsichtbar. Art. 10 Abs. 4 verlangt die Berücksichtigung der geografischen, kontextuellen und verhaltensbezogenen Merkmale des Einsatzumfelds; das Versäumnis erzeugt mittelbare Diskriminierung und macht die Subgruppen-Leistungsangaben nach Art. 13 Abs. 3 unwahr.', 'Risk of non-compliance: If subgroups (older people, dialect speakers, rare medical conditions) are missing from the training set, the model fails precisely for these persons with a markedly higher error rate – invisible in the aggregate metric. Art. 10(4) requires the geographical, contextual and behavioural characteristics of the deployment setting to be taken into account; the omission produces indirect discrimination and renders the subgroup performance statements under Art. 13(3) untrue.', 'AIACT'),
  ('DR-AIACT-A-04.5', 'Delta-Pack', 'Risiko bei Nichterfüllung: Ohne Datensatz-Versionierung kann bei einem Vorfall nicht ermittelt werden, mit welchen Daten das produktive Modell tatsächlich trainiert wurde; Reproduktion, Ursachenanalyse und gezielter Rollback sind unmöglich. Die technische Dokumentation nach Anhang IV verliert ihre Beweiskraft, weil sie sich auf einen nicht mehr identifizierbaren Datenstand bezieht, und Behördenanfragen nach Art. 21 können nicht belastbar beantwortet werden.', 'Risk of non-compliance: Without dataset versioning it cannot be determined after an incident which data the production model was actually trained on; reproduction, root-cause analysis and targeted rollback are impossible. The technical documentation under Annex IV loses its evidential value because it refers to a data state that can no longer be identified, and authority requests under Art. 21 cannot be answered reliably.', 'AIACT'),
  ('DR-AIACT-A-04.6', 'Delta-Pack', 'Risiko bei Nichterfüllung: Werden zugekaufte oder gescrapte Datensätze ohne Lizenzprüfung genutzt, enthält das Modell möglicherweise urheberrechtlich geschützte Werke oder personenbezogene Daten ohne Rechtsgrundlage, und dieser Rechtsmangel lässt sich nicht mehr aus dem Modell entfernen. Neben Unterlassungs- und Schadensersatzansprüchen der Rechteinhaber drohen bei GPAI-Modellen ein Verstoß gegen Art. 53 Abs. 1 lit. c (Art. 101: bis 3 % des Umsatzes) und im schlimmsten Fall der Zwang zum Neutraining.', 'Risk of non-compliance: If purchased or scraped datasets are used without a licence check, the model may embed copyrighted works or personal data without legal basis, and this defect cannot be removed from the model afterwards. Beyond injunctions and damages claims by rights holders, GPAI models face a breach of Art. 53(1)(c) (Art. 101: up to 3 % of turnover) and, in the worst case, forced retraining.', 'AIACT'),
  ('DR-AIACT-A-04.7', 'Delta-Pack', 'Risiko bei Nichterfüllung: Nach einem Modell-Update mit neuen Daten ändern sich Verteilung und Bias-Profil; wird die Datenqualität nicht erneut bewertet, ist ein zuvor fairer Datensatz plötzlich verzerrt, ohne dass jemand es bemerkt. Die Nachbetriebsbeobachtung nach Art. 72 und das iterative Risikomanagement nach Art. 9 Abs. 2 setzen genau diese Re-Evaluation voraus; ihr Fehlen führt zum Auseinanderfallen von dokumentierter und tatsächlicher Datengrundlage.', 'Risk of non-compliance: After a model update with new data, distribution and bias profile change; if data quality is not reassessed, a previously fair dataset is suddenly skewed without anyone noticing. Post-market monitoring under Art. 72 and iterative risk management under Art. 9(2) presuppose exactly this re-evaluation; its absence lets the documented and the actual data basis drift apart.', 'AIACT'),
  ('DR-AIACT-A-05.1', 'Delta-Pack', 'Risiko bei Nichterfüllung: Eine vage Zweckbeschreibung („Unterstützung der Sachbearbeitung“) lässt offen, ob das System unter Anhang III fällt, und erlaubt eine schleichende Zweckausweitung, die nach Art. 25 zur Anbieterrolle führt. Anhang IV Nr. 1 lit. a verlangt die präzise Zweckbestimmung; ohne sie haben Risikoanalyse, Gebrauchsanweisung und Konformitätserklärung keinen Bezugspunkt, und die Dokumentation wird von notifizierter Stelle oder Behörde als unzureichend zurückgewiesen.', 'Risk of non-compliance: A vague purpose statement (''support for case handling'') leaves open whether the system falls under Annex III and allows gradual purpose creep that turns the organisation into a provider under Art. 25. Annex IV No. 1(a) requires a precise intended purpose; without it, risk analysis, instructions for use and declaration of conformity have no reference point, and the documentation is rejected as inadequate by the notified body or authority.', 'AIACT'),
  ('DR-AIACT-A-05.2', 'Delta-Pack', 'Risiko bei Nichterfüllung: Ohne Architektur- und Komponentenbeschreibung kann weder das eigene Sicherheitsteam noch ein Prüfer nachvollziehen, wo Modell, Vorverarbeitung, Schnittstellen und Drittdienste sitzen – Schwachstellen und Datenflüsse bleiben unbekannt. Anhang IV Nr. 2 lit. b–c fordert diese Beschreibung ausdrücklich; die technische Dokumentation ist ohne sie unvollständig, was die Konformitätsbewertung blockiert und Behördenanfragen nach Art. 21 unbeantwortbar macht.', 'Risk of non-compliance: Without an architecture and component description neither the internal security team nor an assessor can trace where model, pre-processing, interfaces and third-party services sit – vulnerabilities and data flows remain unknown. Annex IV No. 2(b)–(c) explicitly requires this description; without it the technical documentation is incomplete, which blocks the conformity assessment and makes authority requests under Art. 21 unanswerable.', 'AIACT'),
  ('DR-AIACT-A-05.3', 'Delta-Pack', 'Risiko bei Nichterfüllung: Eine Gesamtgenauigkeit von 95 % kaschiert, dass das Modell bei einer Minderheitengruppe nur 70 % erreicht; ohne Subgruppen-Metriken wird diese Ungleichbehandlung weder erkannt noch dem Betreiber mitgeteilt. Art. 13 Abs. 3 lit. b ii verlangt Angaben zur Genauigkeit für bestimmte Personengruppen; fehlen sie, ist die Gebrauchsanweisung irreführend, und die Diskriminierung wird erst durch Beschwerden Betroffener oder Presse öffentlich.', 'Risk of non-compliance: An overall accuracy of 95 % masks that the model reaches only 70 % for a minority group; without subgroup metrics this unequal treatment is neither detected nor communicated to the deployer. Art. 13(3)(b)(ii) requires accuracy information for specific groups of persons; without it the instructions for use are misleading, and the discrimination becomes public only through complaints or press reports.', 'AIACT'),
  ('DR-AIACT-A-05.4', 'Delta-Pack', 'Risiko bei Nichterfüllung: Ohne lückenlose Versionshistorie ist nicht mehr feststellbar, welche Modellversion eine bestimmte Entscheidung getroffen hat; bei Beschwerden oder Vorfällen fehlt die Zuordnung zwischen Ergebnis, Modellstand und Konformitätserklärung. Anhang IV Nr. 1 lit. b verlangt die Dokumentation aller Versionen und ihrer Änderungen; wesentliche Änderungen bleiben so unerkannt, und die erneute Konformitätsbewertung nach Art. 43 Abs. 4 wird verpasst.', 'Risk of non-compliance: Without a complete version history it is no longer possible to establish which model version made a particular decision; in complaints or incidents the link between outcome, model state and declaration of conformity is missing. Annex IV No. 1(b) requires documentation of all versions and their changes; substantial modifications go unnoticed and the renewed conformity assessment under Art. 43(4) is missed.', 'AIACT'),
  ('DR-AIACT-A-05.5', 'Delta-Pack', 'Risiko bei Nichterfüllung: Werden bekannte Einschränkungen und vorhersehbare Fehlanwendungen nicht dokumentiert, setzt der Betreiber das System außerhalb seiner validierten Grenzen ein – etwa ein für Deutsch trainiertes Modell für türkischsprachige Anträge –, und Fehlentscheidungen häufen sich. Art. 13 Abs. 3 lit. b iii–iv verlangt diese Angaben; ihr Fehlen macht den Anbieter für Schäden aus vorhersehbarem Missbrauch haftbar und verhindert eine wirksame menschliche Aufsicht nach Art. 14.', 'Risk of non-compliance: If known limitations and reasonably foreseeable misuse are not documented, the deployer uses the system outside its validated boundaries – for instance a model trained on German applied to Turkish-language applications – and wrong decisions accumulate. Art. 13(3)(b)(iii)–(iv) requires this information; its absence makes the provider liable for harm from foreseeable misuse and defeats effective human oversight under Art. 14.', 'AIACT'),
  ('DR-AIACT-A-05.6', 'Delta-Pack', 'Risiko bei Nichterfüllung: Ohne Inventar der Drittkomponenten (Foundation Model, Bibliotheken, Cloud-APIs) bleiben Lizenzänderungen, Sicherheitslücken oder die Abkündigung eines Basismodells unbemerkt, bis das System ausfällt oder unsicher wird. Anhang IV Nr. 2 lit. a fordert die Beschreibung, wie das System mit externer Hard- und Software interagiert; fehlt sie, kann die Verantwortungsverteilung entlang der Wertschöpfungskette nach Art. 25 nicht belegt werden.', 'Risk of non-compliance: Without an inventory of third-party components (foundation model, libraries, cloud APIs), licence changes, vulnerabilities or the discontinuation of a base model go unnoticed until the system fails or becomes insecure. Annex IV No. 2(a) requires a description of how the system interacts with external hardware and software; without it the allocation of responsibility along the value chain under Art. 25 cannot be evidenced.', 'AIACT'),
  ('DR-AIACT-A-06.1', 'Delta-Pack', 'Risiko bei Nichterfüllung: Ohne automatische Protokollierung jeder Hochrisiko-Entscheidung kann im Beschwerdefall nicht rekonstruiert werden, welche Eingaben, Modellversion und Konfidenz zu einem Ergebnis geführt haben – die Erläuterung gegenüber Betroffenen nach Art. 86 ist unmöglich. Art. 12 macht die Protokollierung zur Konstruktionspflicht und Art. 26 Abs. 5 zur Betreiberpflicht; fehlende Logs sind ein Verstoß nach Art. 99 Abs. 4 (bis 15 Mio. €/3 %) und lassen jede Vorfalluntersuchung ins Leere laufen.', 'Risk of non-compliance: Without automatic logging of every high-risk decision it cannot be reconstructed in a complaint which inputs, model version and confidence led to an outcome – the explanation owed to affected persons under Art. 86 becomes impossible. Art. 12 makes logging a design obligation and Art. 26(5) a deployer obligation; missing logs are a breach under Art. 99(4) (up to EUR 15 million/3 %) and leave every incident investigation empty-handed.', 'AIACT'),
  ('DR-AIACT-A-06.2', 'Delta-Pack', 'Risiko bei Nichterfüllung: Protokolle, die nachträglich änderbar sind, verlieren im Streitfall ihren Beweiswert; ein Angreifer oder ein Mitarbeiter unter Druck kann Spuren fehlerhafter Entscheidungen beseitigen, ohne dass es auffällt. Art. 12 Abs. 1 fordert Aufzeichnungen, die Rückverfolgbarkeit gewährleisten, und Art. 19 die Aufbewahrung unter Kontrolle des Anbieters; manipulierbare Logs erfüllen weder das eine noch das andere und schwächen die Verteidigungsposition in jedem Haftungsverfahren.', 'Risk of non-compliance: Logs that can be altered after the fact lose their evidential value in a dispute; an attacker or an employee under pressure can erase traces of faulty decisions unnoticed. Art. 12(1) requires records that ensure traceability and Art. 19 their retention under the provider''s control; tamperable logs satisfy neither and weaken the defence in every liability proceeding.', 'AIACT'),
  ('DR-AIACT-A-06.3', 'Delta-Pack', 'Risiko bei Nichterfüllung: Ohne definierte Aufbewahrungsfrist werden Protokolle entweder zu früh gelöscht (und fehlen dann bei einer Beschwerde, die erst Monate später eingeht) oder unbegrenzt gespeichert und verstoßen gegen die DSGVO-Speicherbegrenzung. Art. 19 Abs. 1 und Art. 26 Abs. 6 verlangen mindestens sechs Monate; zu früh gelöschte Logs sind ein sanktionsbewehrter Verstoß und machen die Meldung schwerwiegender Vorfälle nach Art. 73 inhaltlich unmöglich.', 'Risk of non-compliance: Without a defined retention period, logs are either deleted too early (and are missing when a complaint arrives months later) or kept indefinitely in breach of GDPR storage limitation. Art. 19(1) and Art. 26(6) require at least six months; prematurely deleted logs are a sanctionable breach and make substantive reporting of serious incidents under Art. 73 impossible.', 'AIACT'),
  ('DR-AIACT-A-07.1', 'Delta-Pack', 'Risiko bei Nichterfüllung: Ohne übergebene Gebrauchsanweisung betreibt der Betreiber das System blind – er kennt weder die zulässigen Einsatzbedingungen noch die Aufsichtsmaßnahmen, und sein Betrieb nach Art. 26 Abs. 1 kann nicht gebrauchsanweisungskonform sein. Art. 16 lit. b macht die Bereitstellung zur Anbieterpflicht; ihr Fehlen ist ein Verstoß nach Art. 99 Abs. 4 (bis 15 Mio. €/3 %) und verlagert die Haftung für Fehlanwendungen vollständig auf den Anbieter.', 'Risk of non-compliance: Without instructions for use the deployer runs the system blind – it knows neither the permitted operating conditions nor the oversight measures, and its operation under Art. 26(1) cannot be in line with instructions that do not exist. Art. 16(b) makes provision of the instructions a provider obligation; their absence is a breach under Art. 99(4) (up to EUR 15 million/3 %) and shifts liability for misuse entirely onto the provider.', 'AIACT'),
  ('DR-AIACT-A-07.2', 'Delta-Pack', 'Risiko bei Nichterfüllung: Unklar dokumentierte Fähigkeiten führen zu Übervertrauen – Bediener nutzen das System für Aufgaben, für die es nie validiert wurde, und interpretieren Konfidenzwerte als Gewissheit. Art. 13 Abs. 3 lit. b verlangt die Angabe von Leistungsniveau, bekannten Umständen mit Risikopotenzial und Genauigkeitsgrenzen; ohne sie ist die Transparenzpflicht verletzt, und der Betreiber kann seine Sorgfaltspflichten nach Art. 26 nicht erfüllen.', 'Risk of non-compliance: Poorly documented capabilities breed over-reliance – operators use the system for tasks it was never validated for and read confidence scores as certainty. Art. 13(3)(b) requires disclosure of performance level, known circumstances with risk potential and accuracy limits; without them the transparency obligation is breached and the deployer cannot meet its duties of care under Art. 26.', 'AIACT'),
  ('DR-AIACT-A-07.3', 'Delta-Pack', 'Risiko bei Nichterfüllung: Ohne beschriebene Wartungsintervalle und Update-Verfahren laufen Systeme mit veralteten Modellständen und ungepatchten Bibliotheken weiter; Sicherheitsupdates des Anbieters kommen beim Betreiber nie an. Art. 13 Abs. 3 lit. e verlangt Angaben zu Wartungs- und Pflegemaßnahmen einschließlich Software-Updates; das Versäumnis erzeugt eine Lücke zwischen dem konformitätsbewerteten und dem tatsächlich betriebenen System.', 'Risk of non-compliance: Without documented maintenance intervals and update procedures, systems keep running on outdated model states and unpatched libraries; the provider''s security updates never reach the deployer. Art. 13(3)(e) requires information on maintenance and care measures including software updates; the omission opens a gap between the system that was conformity-assessed and the one actually in operation.', 'AIACT'),
  ('DR-AIACT-A-07.4', 'Delta-Pack', 'Risiko bei Nichterfüllung: Erkennt ein Betreiber eine Fehlfunktion, kennt aber keinen Meldeweg, bleibt der Anbieter uninformiert, korrigierende Maßnahmen nach Art. 20 unterbleiben, und andere Betreiber desselben Systems laufen in dasselbe Problem. Art. 26 Abs. 5 verpflichtet den Betreiber, den Anbieter unverzüglich zu informieren; ohne definierten Kanal wird die Frist für die Meldung schwerwiegender Vorfälle nach Art. 73 (höchstens 15 Tage) faktisch verpasst.', 'Risk of non-compliance: If a deployer detects a malfunction but has no reporting channel, the provider stays uninformed, corrective actions under Art. 20 do not happen, and other deployers of the same system run into the same problem. Art. 26(5) obliges the deployer to inform the provider without undue delay; without a defined channel the deadline for reporting serious incidents under Art. 73 (at most 15 days) is effectively missed.', 'AIACT'),
  ('DR-AIACT-A-07.5', 'Delta-Pack', 'Risiko bei Nichterfüllung: Nach einem Modell- oder Funktionsupdate beschreibt die alte Gebrauchsanweisung Grenzen und Bedienschritte, die nicht mehr stimmen – der Betreiber verlässt sich auf Aufsichtsmechanismen, die es so nicht mehr gibt. Die Informationspflicht nach Art. 13 gilt für das jeweils in Verkehr befindliche System; eine überholte Anleitung ist eine unrichtige Anbieterinformation und entwertet die Betreiberaufsicht nach Art. 26.', 'Risk of non-compliance: After a model or feature update the old instructions describe limits and operating steps that no longer hold – the deployer relies on oversight mechanisms that no longer exist in that form. The information obligation under Art. 13 applies to the system as currently placed on the market; outdated instructions are incorrect provider information and undermine deployer oversight under Art. 26.', 'AIACT'),
  ('DR-AIACT-A-08.1', 'Delta-Pack', 'Risiko bei Nichterfüllung: Ohne schriftlichen Override-Prozess weiß die Aufsichtsperson im Ernstfall nicht, ob und wie sie eine KI-Ausgabe außer Kraft setzen darf; aus Unsicherheit wird die Entscheidung übernommen, obwohl sie erkennbar falsch ist. Art. 14 Abs. 4 lit. d verlangt genau diese Möglichkeit, das Ergebnis zu missachten oder rückgängig zu machen; ihr Fehlen bedeutet, dass die menschliche Aufsicht nur auf dem Papier existiert, und ist ein Verstoß gegen eine Kernanforderung für Hochrisiko-Systeme.', 'Risk of non-compliance: Without a written override procedure the oversight person does not know in the critical moment whether and how an AI output may be set aside; out of uncertainty the decision is adopted even though it is visibly wrong. Art. 14(4)(d) requires precisely this ability to disregard or reverse the output; its absence means human oversight exists only on paper and breaches a core requirement for high-risk systems.', 'AIACT'),
  ('DR-AIACT-A-08.2', 'Delta-Pack', 'Risiko bei Nichterfüllung: Ungeschulte Aufsichtspersonen können Fehlausgaben nicht von korrekten unterscheiden und wissen nicht, in welchen Situationen das System unzuverlässig wird – die Aufsicht degeneriert zur Abnickfunktion. Art. 26 Abs. 2 verlangt Aufsichtspersonen mit der erforderlichen Kompetenz, Art. 4 die KI-Kompetenz aller beteiligten Mitarbeiter; fehlende Schulungsnachweise sind ein unmittelbar prüfbarer Betreiberverstoß nach Art. 99 Abs. 4.', 'Risk of non-compliance: Untrained oversight staff cannot tell faulty outputs from correct ones and do not know in which situations the system becomes unreliable – oversight degenerates into rubber-stamping. Art. 26(2) requires oversight persons with the necessary competence and Art. 4 AI literacy for all staff involved; missing training records are a deployer breach under Art. 99(4) that an inspector can verify immediately.', 'AIACT'),
  ('DR-AIACT-A-08.3', 'Delta-Pack', 'Risiko bei Nichterfüllung: Ohne gezielte Gegenmaßnahmen (Begründungszwang, Stichproben, Entscheidungspausen) übernehmen Bediener nach kurzer Zeit nahezu alle KI-Vorschläge unbesehen – Zustimmungsquoten über 90 % auch bei falschen Ausgaben sind dokumentiert. Art. 14 Abs. 4 lit. b fordert ausdrücklich, dass Aufsichtspersonen sich der Automatisierungsverzerrung bewusst bleiben; ist das nicht organisatorisch abgesichert, wird jede Fehlentscheidung des Systems ungefiltert zur Entscheidung gegenüber Betroffenen.', 'Risk of non-compliance: Without deliberate countermeasures (mandatory justification, spot checks, decision pauses) operators soon accept almost every AI suggestion unexamined – acceptance rates above 90 % even for wrong outputs are documented. Art. 14(4)(b) explicitly requires oversight persons to remain aware of automation bias; if this is not secured organisationally, every faulty system output passes unfiltered into a decision affecting real people.', 'AIACT'),
  ('DR-AIACT-A-08.4', 'Delta-Pack', 'Risiko bei Nichterfüllung: Werden Overrides nicht erfasst, bleibt unsichtbar, ob die Aufsicht überhaupt eingreift (null Overrides = Automation Bias) oder ob sie ständig korrigieren muss (Signal für Modellversagen). Ohne diese Auswertung kann der Betreiber die Überwachungspflicht nach Art. 26 Abs. 5 nicht sinnvoll wahrnehmen, und der Anbieter erhält keine Rückmeldung für die Nachbetriebsbeobachtung nach Art. 72.', 'Risk of non-compliance: If overrides are not recorded, it stays invisible whether oversight intervenes at all (zero overrides = automation bias) or has to correct constantly (a signal of model failure). Without this analysis the deployer cannot meaningfully perform its monitoring duty under Art. 26(5), and the provider receives no feedback for post-market monitoring under Art. 72.', 'AIACT'),
  ('DR-AIACT-A-08.5', 'Delta-Pack', 'Risiko bei Nichterfüllung: Kann der laufende KI-Prozess nicht jederzeit angehalten werden, läuft ein fehlerhaftes System bei einem erkannten Problem weiter und produziert bis zur technischen Abschaltung weitere Fehlentscheidungen – bei automatisierten Ablehnungen tausende in Minuten. Art. 14 Abs. 4 lit. e verlangt eine „Stopp-Taste“ oder ein vergleichbares Verfahren; ihr Fehlen ist ein Konstruktionsmangel, der die Konformität nach Art. 43 ausschließt.', 'Risk of non-compliance: If the running AI process cannot be halted at any time, a faulty system keeps operating after a problem is detected and produces further wrong decisions until technical shutdown – thousands within minutes in automated rejections. Art. 14(4)(e) requires a ''stop'' button or an equivalent procedure; its absence is a design defect that rules out conformity under Art. 43.', 'AIACT'),
  ('DR-AIACT-A-08.6', 'Delta-Pack', 'Risiko bei Nichterfüllung: Ist die Aufsichtsrolle nicht in Stellenbeschreibungen verankert, gilt die Kontrolle der KI als Zusatzaufgabe „nebenbei“, für die weder Zeit noch Befugnis eingeplant ist; bei Personalwechsel geht die Funktion unbemerkt verloren. Art. 26 Abs. 2 verlangt, dass der Betreiber die Aufsicht natürlichen Personen mit Kompetenz, Ausbildung und Befugnis überträgt – ohne organisatorische Verankerung ist diese Zuweisung nicht nachweisbar.', 'Risk of non-compliance: If the oversight role is not anchored in job descriptions, controlling the AI counts as a side task for which neither time nor authority is allocated; when staff change, the function silently disappears. Art. 26(2) requires the deployer to assign oversight to natural persons with competence, training and authority – without organisational anchoring this assignment cannot be evidenced.', 'AIACT'),
  ('DR-AIACT-A-09.1', 'Delta-Pack', 'Risiko bei Nichterfüllung: Ohne vorab definierte und gemessene Genauigkeitsmetriken gibt es keinen Referenzwert, an dem ein Leistungsabfall im Betrieb erkannt werden könnte, und die Angaben in der Gebrauchsanweisung beruhen auf Schätzung. Art. 15 Abs. 1 und 3 verlangen ein angemessenes, deklariertes Genauigkeitsniveau; fehlt die Messung, ist die Konformitätserklärung ohne Tatsachengrundlage und jede Aussage gegenüber Betreibern potenziell irreführend.', 'Risk of non-compliance: Without accuracy metrics defined and measured in advance there is no baseline against which performance degradation in operation could be detected, and the figures in the instructions for use rest on estimates. Art. 15(1) and (3) require an appropriate, declared level of accuracy; without measurement the declaration of conformity has no factual basis and every statement to deployers is potentially misleading.', 'AIACT'),
  ('DR-AIACT-A-09.2', 'Delta-Pack', 'Risiko bei Nichterfüllung: Ohne Robustheitsprüfung lassen sich Modelle durch gezielt manipulierte Eingaben (Adversarial Examples, Prompt Injection, Datenvergiftung) zu falschen Ausgaben zwingen – ein Angreifer umgeht die Betrugserkennung oder erzwingt eine Kreditzusage. Art. 15 Abs. 4–5 fordern Widerstandsfähigkeit gegen Fehler und gegen Versuche Dritter, das Verhalten zu verändern; ungetestete Angriffsflächen sind ein Sicherheitsmangel mit Melde- und Haftungsfolgen, sobald sie ausgenutzt werden.', 'Risk of non-compliance: Without robustness testing, models can be forced into wrong outputs by crafted inputs (adversarial examples, prompt injection, data poisoning) – an attacker bypasses fraud detection or forces a loan approval. Art. 15(4)–(5) require resilience against errors and against third-party attempts to alter behaviour; untested attack surfaces are a security defect with reporting and liability consequences as soon as they are exploited.', 'AIACT'),
  ('DR-AIACT-A-09.3', 'Delta-Pack', 'Risiko bei Nichterfüllung: Ungeschützte Modell-Endpunkte, ungesicherte Trainingspipelines und unkontrollierte Zugriffe auf Modellgewichte ermöglichen Modelldiebstahl, Manipulation oder die Extraktion personenbezogener Trainingsdaten. Art. 15 Abs. 5 verlangt KI-spezifische Cybersicherheit; ein Angriff erfüllt zugleich den Tatbestand eines schwerwiegenden Vorfalls nach Art. 73 und einer DSGVO-Datenpanne nach Art. 33 mit 72-Stunden-Frist – für NIS2-pflichtige Unternehmen kommt eine weitere Meldepflicht hinzu.', 'Risk of non-compliance: Unprotected model endpoints, unsecured training pipelines and uncontrolled access to model weights enable model theft, manipulation or extraction of personal training data. Art. 15(5) requires AI-specific cybersecurity; an attack simultaneously constitutes a serious incident under Art. 73 and a GDPR data breach under Art. 33 with its 72-hour deadline – and for NIS2-regulated entities a further reporting obligation.', 'AIACT'),
  ('DR-AIACT-A-09.4', 'Delta-Pack', 'Risiko bei Nichterfüllung: Ohne Überwachung unter Produktionsbedingungen verschlechtert sich die Leistung schleichend, weil sich Eingabedaten, Nutzerverhalten und Umfeld ändern; die dokumentierte Genauigkeit gilt nur noch für den Testtag. Art. 72 verpflichtet den Anbieter zur systematischen Nachbetriebsbeobachtung und Art. 15 Abs. 1 zur Aufrechterhaltung der Genauigkeit über den Lebenszyklus; fehlt beides, werden Fehlentscheidungen erst durch Beschwerden sichtbar.', 'Risk of non-compliance: Without monitoring under production conditions, performance degrades gradually as input data, user behaviour and environment change; the documented accuracy is valid only for the day of testing. Art. 72 obliges the provider to systematic post-market monitoring and Art. 15(1) to maintain accuracy throughout the lifecycle; without both, wrong decisions surface only through complaints.', 'AIACT'),
  ('DR-AIACT-A-09.5', 'Delta-Pack', 'Risiko bei Nichterfüllung: Ohne KI-spezifischen Incident-Response-Prozess weiß bei einem Vorfall (Datenleck über Prompts, massenhafte Fehlentscheidung, Modellmanipulation) niemand, wer das System abschaltet, wer Betroffene und Behörden informiert und wie Beweise gesichert werden. Die Meldefrist nach Art. 73 (höchstens 15 Tage, bei weitverbreiteten Verstößen 2 Tage) wird verpasst, was ein eigenständiger Verstoß nach Art. 99 Abs. 4 ist; parallel laufen DSGVO- und NIS2-Fristen ab.', 'Risk of non-compliance: Without an AI-specific incident response process, nobody knows during an incident (data leakage via prompts, mass wrong decisions, model manipulation) who shuts the system down, who informs affected persons and authorities and how evidence is preserved. The reporting deadline under Art. 73 (at most 15 days, 2 days for widespread infringements) is missed, which is a separate breach under Art. 99(4); GDPR and NIS2 deadlines expire in parallel.', 'AIACT'),
  ('DR-AIACT-A-09.6', 'Delta-Pack', 'Risiko bei Nichterfüllung: Ohne Red-Teaming bleiben Jailbreaks, Datenabflüsse und unsichere Ausgabeverhalten unentdeckt, bis externe Angreifer oder die Öffentlichkeit sie finden – oft mit Screenshots in sozialen Medien. Art. 15 Abs. 5 verlangt Schutzmaßnahmen gegen KI-spezifische Angriffe, und für GPAI mit systemischem Risiko ist Adversarial Testing nach Art. 55 Abs. 1 lit. a ausdrückliche Pflicht (Art. 101: bis 3 % des Umsatzes); nicht getestete Sicherheit ist nicht belegbare Sicherheit.', 'Risk of non-compliance: Without red teaming, jailbreaks, data exfiltration and unsafe output behaviour remain undiscovered until external attackers or the public find them – often with screenshots on social media. Art. 15(5) requires safeguards against AI-specific attacks, and for GPAI with systemic risk adversarial testing is an explicit duty under Art. 55(1)(a) (Art. 101: up to 3 % of turnover); untested security is security that cannot be evidenced.', 'AIACT'),
  ('DR-AIACT-A-10.1', 'Delta-Pack', 'Risiko bei Nichterfüllung: Ohne dokumentiertes Qualitätsmanagementsystem hängt die Konformität von einzelnen Personen ab; Verantwortlichkeiten sind unklar und Prozesse nicht wiederholbar. Art. 17 Abs. 1 macht das QMS zur Anbieterpflicht, und die Konformitätsbewertung nach Anhang VI/VII prüft es ausdrücklich – fehlende QMS-Dokumentation ist ein Verstoß nach Art. 99 Abs. 4 (bis 15 Mio. €/3 %) und verhindert die CE-Kennzeichnung.', 'Risk of non-compliance: Without a documented quality management system, conformity depends on individual people; responsibilities are unclear and processes are not repeatable. Art. 17(1) makes the QMS a provider obligation and the conformity assessment under Annex VI/VII examines it explicitly – missing QMS documentation is a breach under Art. 99(4) (up to EUR 15 million/3 %) and prevents CE marking.', 'AIACT'),
  ('DR-AIACT-A-10.2', 'Delta-Pack', 'Risiko bei Nichterfüllung: Ohne definierte Prüf-, Test- und Validierungsverfahren gelangen Modelle ungeprüft in Produktion; Design-Kontrollen, Datenmanagement und Freigabekriterien existieren nur informell. Art. 17 Abs. 1 lit. b–e und g verlangen genau diese Verfahren; ihr Fehlen macht die Qualitätssicherung im Audit nicht nachvollziehbar und lässt Fehler, die im Entwicklungsprozess hätten abgefangen werden müssen, bei Betroffenen ankommen.', 'Risk of non-compliance: Without defined examination, test and validation procedures, models reach production unchecked; design controls, data management and release criteria exist only informally. Art. 17(1)(b)–(e) and (g) require exactly these procedures; their absence makes quality assurance untraceable in an audit and lets errors that should have been caught in development reach affected persons.', 'AIACT'),
  ('DR-AIACT-A-10.3', 'Delta-Pack', 'Risiko bei Nichterfüllung: Ohne etablierten Management-Review erfährt die Leitung nicht, ob das QMS wirkt, welche Vorfälle aufgetreten sind und wo Ressourcen fehlen; KI-Compliance bleibt eine Angelegenheit der Fachebene ohne Entscheidungsbefugnis. Art. 17 Abs. 1 lit. m verlangt einen Rechenschaftsrahmen mit Verantwortung des Managements; fehlt er, ist die Leitungsverantwortung im Verstoßfall nicht delegierbar, und persönliche Haftung der Organe rückt näher.', 'Risk of non-compliance: Without an established management review, leadership does not learn whether the QMS works, which incidents occurred and where resources are lacking; AI compliance remains a matter for specialists without decision-making authority. Art. 17(1)(m) requires an accountability framework with management responsibility; without it, leadership responsibility cannot be delegated in a breach scenario and personal liability of officers draws closer.', 'AIACT'),
  ('DR-AIACT-A-10.4', 'Delta-Pack', 'Risiko bei Nichterfüllung: Werden Erkenntnisse aus Vorfällen, Beschwerden und Nachbetriebsbeobachtung nicht systematisch in Verbesserungen überführt, wiederholen sich dieselben Fehler mit jedem Release. Art. 17 Abs. 1 lit. h koppelt das QMS ausdrücklich an das Nachbetriebssystem nach Art. 72; ein QMS ohne nachweisbaren Verbesserungszyklus gilt als nicht wirksam und wird bei der Überwachung durch die notifizierte Stelle beanstandet.', 'Risk of non-compliance: If lessons from incidents, complaints and post-market monitoring are not systematically turned into improvements, the same errors recur with every release. Art. 17(1)(h) explicitly ties the QMS to the post-market monitoring system under Art. 72; a QMS without a demonstrable improvement cycle is deemed ineffective and is flagged during surveillance by the notified body.', 'AIACT'),
  ('DR-AIACT-A-10.5', 'Delta-Pack', 'Risiko bei Nichterfüllung: Werden Lieferanten von Modellen, Daten oder Komponenten nicht in das QMS eingebunden, fehlen vertragliche Zusagen zu Dokumentation, Updates und Vorfallmeldung – der Anbieter kann seine eigenen Pflichten nicht erfüllen, weil ihm die Informationen fehlen. Art. 17 Abs. 1 lit. l und Art. 25 Abs. 4 verlangen die Steuerung der Lieferkette per schriftlicher Vereinbarung; ohne sie trägt der Anbieter die volle Haftung für Mängel, die beim Zulieferer entstanden sind.', 'Risk of non-compliance: If suppliers of models, data or components are not integrated into the QMS, there are no contractual commitments on documentation, updates and incident reporting – the provider cannot fulfil its own obligations because it lacks the information. Art. 17(1)(l) and Art. 25(4) require supply-chain control through written agreements; without them the provider bears full liability for defects that originated with the supplier.', 'AIACT'),
  ('DR-AIACT-A-11.1', 'Delta-Pack', 'Risiko bei Nichterfüllung: Ohne abgeschlossenes Konformitätsbewertungsverfahren darf ein Hochrisiko-System nicht in Verkehr gebracht oder in Betrieb genommen werden; jedes Inverkehrbringen ist rechtswidrig, und Kunden können Verträge wegen Rechtsmangels anfechten. Art. 16 lit. f und Art. 43 machen die Bewertung zur Voraussetzung; die Marktüberwachung kann nach Art. 79 Rücknahme und Rückruf anordnen und nach Art. 99 Abs. 4 bis 15 Mio. €/3 % verhängen.', 'Risk of non-compliance: Without a completed conformity assessment procedure a high-risk system may not be placed on the market or put into service; every placing is unlawful and customers can challenge contracts for legal defect. Art. 16(f) and Art. 43 make the assessment a precondition; market surveillance can order withdrawal and recall under Art. 79 and impose up to EUR 15 million/3 % under Art. 99(4).', 'AIACT'),
  ('DR-AIACT-A-11.2', 'Delta-Pack', 'Risiko bei Nichterfüllung: Fehlt die unterzeichnete EU-Konformitätserklärung oder ist sie nach wenigen Jahren nicht mehr auffindbar, kann der Anbieter bei einer Behördenanfrage die Konformität nicht belegen – das Dokument, mit dem er die Verantwortung übernimmt, existiert nicht. Art. 47 und Art. 18 Abs. 1 lit. d verlangen Ausstellung und zehnjährige Aufbewahrung; die Verletzung ist ein formaler Verstoß nach Art. 99 Abs. 4 und führt zur Anordnung des Marktrückzugs bis zur Nachlieferung.', 'Risk of non-compliance: If the signed EU declaration of conformity is missing or cannot be located after a few years, the provider cannot prove conformity when the authority asks – the document by which it assumes responsibility does not exist. Art. 47 and Art. 18(1)(d) require issuance and ten-year retention; the violation is a formal breach under Art. 99(4) and leads to a market withdrawal order until the document is supplied.', 'AIACT'),
  ('DR-AIACT-A-11.3', 'Delta-Pack', 'Risiko bei Nichterfüllung: Ohne CE-Kennzeichnung (bei rein digitalen Systemen digital angebracht und aus der Schnittstelle abrufbar) fehlt das sichtbare Konformitätssignal für Betreiber und Behörden; das System gilt formal als nicht verkehrsfähig. Art. 48 und Art. 16 lit. h verlangen die Kennzeichnung; ihr Fehlen ist ein leicht feststellbarer Formalverstoß – ebenso wie eine CE-Kennzeichnung ohne bestandene Bewertung, die als Täuschung der Behörde bewertet wird.', 'Risk of non-compliance: Without CE marking (affixed digitally and retrievable from the interface for purely digital systems) the visible conformity signal for deployers and authorities is missing; the system is formally not marketable. Art. 48 and Art. 16(h) require the marking; its absence is an easily detected formal breach – as is a CE mark affixed without a passed assessment, which is treated as deceiving the authority.', 'AIACT'),
  ('DR-AIACT-A-11.4', 'Delta-Pack', 'Risiko bei Nichterfüllung: Ohne Eintrag in der EU-Datenbank ist das Hochrisiko-System für Öffentlichkeit und Marktüberwachung unsichtbar; der Betrieb erfolgt außerhalb des Transparenzsystems und wird bei einer Prüfung als bewusste Umgehung gewertet. Art. 49 macht die Registrierung vor dem Inverkehrbringen zur Pflicht für Anbieter und bei Anhang-III-Systemen auch für Behörden als Betreiber; das Versäumnis ist ein Verstoß nach Art. 99 Abs. 4 und für öffentliche Stellen zusätzlich ein Reputationsproblem.', 'Risk of non-compliance: Without an entry in the EU database the high-risk system is invisible to the public and to market surveillance; it operates outside the transparency regime and is treated on inspection as deliberate circumvention. Art. 49 makes registration before placing on the market mandatory for providers and, for Annex III systems, for public-authority deployers too; the omission is a breach under Art. 99(4) and, for public bodies, an additional reputational problem.', 'AIACT'),
  ('DR-AIACT-A-11.5', 'Delta-Pack', 'Risiko bei Nichterfüllung: Ein wesentlich geändertes System (neuer Zweck, neues Basismodell, geänderte Entscheidungslogik) läuft mit der alten Konformitätserklärung weiter, die für diese Version nie galt; die CE-Kennzeichnung ist damit materiell falsch. Art. 43 Abs. 4 verlangt eine neue Bewertung bei wesentlichen Änderungen; fehlt sie, ist das Inverkehrbringen der geänderten Version rechtswidrig, mit Rückruf- und Bußgeldrisiko nach Art. 99 Abs. 4.', 'Risk of non-compliance: A substantially modified system (new purpose, new base model, changed decision logic) keeps running under the old declaration of conformity, which never covered this version; the CE marking is thus materially false. Art. 43(4) requires a new assessment for substantial modifications; without it, placing the modified version on the market is unlawful, with recall and fine exposure under Art. 99(4).', 'AIACT'),
  ('DR-AIACT-A-11.6', 'Delta-Pack', 'Risiko bei Nichterfüllung: Kann die Marktüberwachungsbehörde die technische Dokumentation nicht binnen der gesetzten Frist erhalten (weil sie verstreut, unvollständig oder beim Zulieferer liegt), wertet sie das als fehlende Konformität und kann die Marktrücknahme anordnen. Art. 21 verpflichtet zur Herausgabe auf begründetes Verlangen und Art. 74 gibt der Behörde Zugriffsrechte bis hin zum Quellcode; unvollständige oder irreführende Auskünfte werden nach Art. 99 Abs. 5 mit bis zu 7,5 Mio. €/1 % sanktioniert.', 'Risk of non-compliance: If the market surveillance authority cannot obtain the technical documentation within the set deadline (because it is scattered, incomplete or held by a supplier), it treats this as lack of conformity and can order market withdrawal. Art. 21 obliges disclosure on reasoned request and Art. 74 gives the authority access rights up to source code; incomplete or misleading information is sanctioned under Art. 99(5) with up to EUR 7.5 million/1 %.', 'AIACT'),
  ('DR-AIACT-A-12.1', 'Delta-Pack', 'Risiko bei Nichterfüllung: Werden die betroffenen Grundrechte (Nichtdiskriminierung, Datenschutz, Meinungsfreiheit, Zugang zu Sozialleistungen) nicht konkret benannt, bleibt die Grundrechte-Folgenabschätzung eine Formalie ohne Schutzwirkung, und Betroffenengruppen wie Kinder oder Menschen mit Behinderung werden übersehen. Art. 27 Abs. 1 lit. c–d verpflichtet öffentliche Stellen und bestimmte private Betreiber zu dieser Identifikation; ihre Auslassung ist ein Betreiberverstoß nach Art. 99 Abs. 4 und liefert Klägern eine fertige Begründung.', 'Risk of non-compliance: If the affected fundamental rights (non-discrimination, data protection, freedom of expression, access to social benefits) are not named concretely, the fundamental rights impact assessment remains a formality without protective effect, and groups such as children or persons with disabilities are overlooked. Art. 27(1)(c)–(d) obliges public bodies and certain private deployers to this identification; its omission is a deployer breach under Art. 99(4) and hands claimants a ready-made argument.', 'AIACT'),
  ('DR-AIACT-A-12.2', 'Delta-Pack', 'Risiko bei Nichterfüllung: Ohne Einschätzung von Wahrscheinlichkeit und Schwere werden alle Grundrechtsrisiken gleich behandelt – die seltene, aber existenzbedrohende Fehlentscheidung (etwa ein Leistungsentzug) bekommt dieselbe Aufmerksamkeit wie ein kosmetischer Fehler. Art. 27 Abs. 1 lit. d verlangt genau diese Priorisierung; ohne sie sind die Maßnahmen nach lit. f nicht risikoadäquat, und die FRIA kann von der Marktüberwachung als inhaltsleer zurückgewiesen werden.', 'Risk of non-compliance: Without assessing likelihood and severity, all fundamental-rights risks are treated alike – the rare but existential wrong decision (such as withdrawal of benefits) receives the same attention as a cosmetic error. Art. 27(1)(d) requires precisely this prioritisation; without it the measures under point (f) are not proportionate to the risk, and market surveillance can reject the FRIA as devoid of substance.', 'AIACT'),
  ('DR-AIACT-A-12.3', 'Delta-Pack', 'Risiko bei Nichterfüllung: Eine FRIA, die Risiken benennt, aber keine Maßnahmen (Beschwerdeweg, menschliche Prüfung, Ausschluss bestimmter Merkmale) festlegt und umsetzt, dokumentiert das eigene Wissen um den Schaden, ohne ihn zu verhindern – im Prozess der schlechteste Fall. Art. 27 Abs. 1 lit. f verlangt Governance- und Beschwerdemechanismen; fehlen sie, ist die Betreiberpflicht verletzt, und jede Grundrechtsverletzung gilt als vorhersehbar und vermeidbar.', 'Risk of non-compliance: A FRIA that names risks but neither defines nor implements measures (complaint channel, human review, exclusion of certain attributes) documents the organisation''s own knowledge of the harm without preventing it – the worst position in litigation. Art. 27(1)(f) requires governance and complaint mechanisms; without them the deployer obligation is breached and every fundamental-rights violation counts as foreseeable and avoidable.', 'AIACT'),
  ('DR-AIACT-A-12.4', 'Delta-Pack', 'Risiko bei Nichterfüllung: Ist die Mitteilung an die Marktüberwachungsbehörde nicht vorbereitet, muss sie unter Zeitdruck erstellt werden und enthält Lücken oder Widersprüche zur Registrierung in der EU-Datenbank. Art. 27 Abs. 3 verlangt die Mitteilung der FRIA-Ergebnisse mit dem Formular des KI-Büros; eine unterlassene oder unrichtige Mitteilung ist nach Art. 99 Abs. 4 bzw. Abs. 5 sanktionierbar und signalisiert der Behörde mangelnde Governance.', 'Risk of non-compliance: If the notification to the market surveillance authority is not prepared, it has to be produced under time pressure and contains gaps or contradictions with the EU database registration. Art. 27(3) requires notification of the FRIA results using the AI Office template; an omitted or incorrect notification is sanctionable under Art. 99(4) or (5) and signals weak governance to the authority.', 'AIACT'),
  ('DR-AIACT-A-12.5', 'Delta-Pack', 'Risiko bei Nichterfüllung: Eine einmal erstellte FRIA veraltet mit jeder Änderung der Nutzergruppe, des Modells oder der Rechtsprechung; nach einem Jahr beschreibt sie ein System, das so nicht mehr betrieben wird. Art. 27 Abs. 2 verlangt eine Aktualisierung, sobald sich relevante Faktoren ändern; ein veraltetes Dokument gilt als nicht durchgeführte FRIA und nimmt dem Betreiber den Nachweis, seine Sorgfaltspflichten ausgeübt zu haben.', 'Risk of non-compliance: A FRIA drawn up once becomes obsolete with every change in user population, model or case law; after a year it describes a system that is no longer operated that way. Art. 27(2) requires an update as soon as relevant factors change; an outdated document counts as a FRIA not carried out and deprives the deployer of the proof that it exercised its duties of care.', 'AIACT'),
  ('DR-AIACT-A-13.1', 'Delta-Pack', 'Risiko bei Nichterfüllung: Ohne Plan zur Nachbetriebsbeobachtung mit definierten Metriken und Intervallen erfolgt die Überwachung ad hoc oder gar nicht; Leistungsverschlechterungen und neue Risiken werden erst bei Beschwerden sichtbar. Art. 72 Abs. 1–3 verlangt ein dokumentiertes System auf Basis eines Plans, der Teil der technischen Dokumentation ist; ohne ihn ist die Dokumentation unvollständig und die Konformitätsbewertung angreifbar.', 'Risk of non-compliance: Without a post-market monitoring plan with defined metrics and intervals, monitoring happens ad hoc or not at all; performance degradation and new risks become visible only through complaints. Art. 72(1)–(3) requires a documented system based on a plan that forms part of the technical documentation; without it the documentation is incomplete and the conformity assessment contestable.', 'AIACT'),
  ('DR-AIACT-A-13.2', 'Delta-Pack', 'Risiko bei Nichterfüllung: Ohne definierte Schwellenwerte diskutiert das Team bei jedem Leistungsabfall neu, ob es „noch okay“ ist – die Entscheidung zum Nachtraining oder Rückzug wird aus Bequemlichkeit verschoben, während Fehlentscheidungen zunehmen. Art. 20 verpflichtet den Anbieter zu unverzüglichen Korrekturmaßnahmen bis hin zum Rückruf, sobald Grund zur Annahme fehlender Konformität besteht; ohne Schwellenwerte ist dieser Zeitpunkt nicht feststellbar und wird systematisch verpasst.', 'Risk of non-compliance: Without defined thresholds the team re-debates at every performance dip whether it is ''still fine'' – the decision to retrain or withdraw is postponed out of convenience while wrong decisions accumulate. Art. 20 obliges the provider to immediate corrective action up to recall as soon as there is reason to believe the system is non-conforming; without thresholds that moment cannot be identified and is systematically missed.', 'AIACT'),
  ('DR-AIACT-A-13.3', 'Delta-Pack', 'Risiko bei Nichterfüllung: Ohne definierten Meldeprozess wird ein schwerwiegender Vorfall (Tod, Gesundheitsschaden, Grundrechtsverletzung, Störung kritischer Infrastruktur) intern als „Bug“ behandelt, und die Meldung an die Marktüberwachung unterbleibt oder kommt zu spät. Art. 73 setzt Fristen von 15 Tagen, bei Todesfällen 10 Tagen und bei weitverbreiteten Verstößen 2 Tagen; eine verspätete Meldung ist ein eigenständiger Verstoß nach Art. 99 Abs. 4 und wird bei der Bußgeldbemessung als erschwerend gewertet.', 'Risk of non-compliance: Without a defined reporting process a serious incident (death, damage to health, fundamental-rights violation, disruption of critical infrastructure) is handled internally as a ''bug'', and the report to market surveillance is omitted or late. Art. 73 sets deadlines of 15 days, 10 days for deaths and 2 days for widespread infringements; a late report is a separate breach under Art. 99(4) and counts as an aggravating factor when the fine is set.', 'AIACT'),
  ('DR-AIACT-A-13.4', 'Delta-Pack', 'Risiko bei Nichterfüllung: Ohne Drift-Monitoring bemerkt niemand, dass sich die Eingabedaten (Datendrift) oder der Zusammenhang zwischen Merkmalen und Ergebnis (Konzeptdrift) verschoben haben – das Modell trifft mit unveränderter Konfidenz zunehmend falsche Entscheidungen. Art. 15 Abs. 4 verlangt Robustheit gegen Rückkopplungsschleifen und Art. 72 die Beobachtung der Leistung im Betrieb; unerkannter Drift ist die häufigste Ursache schleichender Diskriminierung und macht die Genauigkeitsangaben der Gebrauchsanweisung unwahr.', 'Risk of non-compliance: Without drift monitoring nobody notices that the input data (data drift) or the relationship between features and outcome (concept drift) has shifted – the model makes increasingly wrong decisions with unchanged confidence. Art. 15(4) requires robustness against feedback loops and Art. 72 the observation of performance in operation; undetected drift is the most common cause of creeping discrimination and renders the accuracy statements in the instructions for use untrue.', 'AIACT'),
  ('DR-AIACT-A-14.1', 'Delta-Pack', 'Risiko bei Nichterfüllung: Wird nicht geprüft, ob ein selbst trainiertes oder erheblich feinabgestimmtes Modell als KI-Modell mit allgemeinem Verwendungszweck gilt, entstehen Anbieterpflichten nach Art. 53 (Dokumentation, Urheberrechtsstrategie, Trainingsdaten-Zusammenfassung) unbemerkt – und ab 10²⁵ FLOPs zusätzlich die Meldepflicht an die Kommission nach Art. 52. Das Versäumnis wird nach Art. 101 mit bis zu 15 Mio. € oder 3 % des Umsatzes sanktioniert und macht nachgelagerte Anbieter, die auf dem Modell aufbauen, ebenfalls nicht konform.', 'Risk of non-compliance: If it is not examined whether a self-trained or substantially fine-tuned model qualifies as a general-purpose AI model, provider obligations under Art. 53 (documentation, copyright policy, training-data summary) arise unnoticed – and above 10^25 FLOPs the notification duty to the Commission under Art. 52 as well. The omission is sanctioned under Art. 101 with up to EUR 15 million or 3 % of turnover and leaves downstream providers building on the model non-compliant too.', 'AIACT'),
  ('DR-AIACT-A-14.2', 'Delta-Pack', 'Risiko bei Nichterfüllung: Ohne technische Dokumentation nach Anhang XI/XII können nachgelagerte Anbieter, die das Modell in Hochrisiko-Systeme integrieren, ihre eigenen Pflichten nicht erfüllen und weichen auf Wettbewerber aus. Art. 53 Abs. 1 lit. a–b verlangt die Dokumentation für das KI-Büro und für Integratoren; ihr Fehlen ist nach Art. 101 mit bis zu 3 % des Umsatzes sanktioniert, und das KI-Büro kann nach Art. 91 Informationen anfordern und nach Art. 93 Maßnahmen bis zum Marktrückzug anordnen.', 'Risk of non-compliance: Without technical documentation under Annex XI/XII, downstream providers integrating the model into high-risk systems cannot meet their own obligations and switch to competitors. Art. 53(1)(a)–(b) requires documentation for the AI Office and for integrators; its absence is sanctioned under Art. 101 with up to 3 % of turnover, and the AI Office can request information under Art. 91 and order measures up to market withdrawal under Art. 93.', 'AIACT'),
  ('DR-AIACT-A-14.3', 'Delta-Pack', 'Risiko bei Nichterfüllung: Ohne veröffentlichte Zusammenfassung der Trainingsinhalte können Rechteinhaber nicht prüfen, ob ihre Werke verwendet wurden; das Unternehmen wirkt intransparent und zieht gezielte Auskunfts- und Urheberrechtsklagen an. Art. 53 Abs. 1 lit. d verlangt die Veröffentlichung nach der Vorlage des KI-Büros; das Versäumnis ist nach Art. 101 mit bis zu 3 % des Umsatzes sanktioniert und ein öffentlich sichtbares Compliance-Defizit.', 'Risk of non-compliance: Without a published summary of training content, rights holders cannot check whether their works were used; the company appears opaque and attracts targeted disclosure and copyright claims. Art. 53(1)(d) requires publication using the AI Office template; the omission is sanctioned under Art. 101 with up to 3 % of turnover and is a publicly visible compliance deficit.', 'AIACT'),
  ('DR-AIACT-A-14.4', 'Delta-Pack', 'Risiko bei Nichterfüllung: Ohne Urheberrechtsstrategie werden maschinenlesbare Nutzungsvorbehalte (Opt-outs nach Art. 4 Abs. 3 DSM-Richtlinie) beim Crawling ignoriert, und geschützte Werke fließen ohne Rechtsgrundlage ins Training – das lässt sich nachträglich nicht mehr entfernen. Art. 53 Abs. 1 lit. c verlangt eine Strategie zur Einhaltung des Urheberrechts; neben dem Bußgeld nach Art. 101 (bis 3 %) drohen Unterlassungsansprüche, die den Betrieb des Modells insgesamt gefährden.', 'Risk of non-compliance: Without a copyright policy, machine-readable reservations of rights (opt-outs under Art. 4(3) of the DSM Directive) are ignored during crawling, and protected works flow into training without legal basis – which cannot be undone afterwards. Art. 53(1)(c) requires a policy to comply with copyright law; beyond the fine under Art. 101 (up to 3 %), injunctions threaten the operation of the model as a whole.', 'AIACT'),
  ('DR-AIACT-A-14.5', 'Delta-Pack', 'Risiko bei Nichterfüllung: Ein Modell oberhalb von 10²⁵ FLOPs gilt nach Art. 51 Abs. 2 als Modell mit systemischem Risiko; ohne Adversarial Testing bleiben gefährliche Fähigkeiten (Erzeugung von Schadcode, biologische Anleitungen, großflächige Desinformation) unbewertet. Art. 55 Abs. 1 lit. a verlangt die Modellbewertung inklusive Red-Teaming und lit. c die Meldung schwerwiegender Vorfälle an das KI-Büro; das Versäumnis ist nach Art. 101 mit bis zu 15 Mio. €/3 % sanktioniert, und die Kommission kann Beschränkungen bis zum Marktrückzug anordnen.', 'Risk of non-compliance: A model above 10^25 FLOPs is presumed under Art. 51(2) to carry systemic risk; without adversarial testing, dangerous capabilities (malicious code generation, biological instructions, large-scale disinformation) remain unassessed. Art. 55(1)(a) requires model evaluation including red teaming and point (c) the reporting of serious incidents to the AI Office; the omission is sanctioned under Art. 101 with up to EUR 15 million/3 %, and the Commission can impose restrictions up to market withdrawal.', 'AIACT'),
  ('DR-ISO42001-C-01.1', 'Delta-Pack', 'Risiko bei Nichterfüllung: Ohne genehmigten AIMS-Scope ist unklar, welche Systeme, Standorte und Prozesse dem Managementsystem unterliegen – Schatten-KI in Fachabteilungen bleibt außerhalb jeder Governance. Klausel 4.3 macht den dokumentierten Anwendungsbereich zur Grundvoraussetzung; ein Zertifizierungsaudit endet ohne ihn in einer Hauptabweichung, und die Leitung kann ihre Verpflichtung nach Klausel 5.1 nicht nachweisen.', 'Risk of non-compliance: Without an approved AIMS scope it is unclear which systems, sites and processes fall under the management system – shadow AI in business units stays outside any governance. Clause 4.3 makes the documented scope a basic precondition; a certification audit ends in a major non-conformity without it, and top management cannot demonstrate its commitment under Clause 5.1.', 'ISO42001'),
  ('DR-ISO42001-C-01.2', 'Delta-Pack', 'Risiko bei Nichterfüllung: Ohne eine von der Leitung verabschiedete KI-Politik fehlt der verbindliche Rahmen, an dem sich Beschaffung, Entwicklung und Nutzung messen lassen; jede Abteilung setzt eigene Maßstäbe, und Mitarbeiter nutzen frei verfügbare Tools mit Unternehmensdaten. Klausel 5.2 und Kontrolle A.2.2 verlangen eine dokumentierte, kommunizierte Politik; ihr Fehlen ist eine Hauptabweichung im Audit und dokumentiert gegenüber Aufsicht und Kunden, dass das Management KI nicht steuert.', 'Risk of non-compliance: Without an AI policy adopted by top management there is no binding frame against which procurement, development and use can be measured; each department sets its own standards and staff use freely available tools with company data. Clause 5.2 and control A.2.2 require a documented, communicated policy; its absence is a major non-conformity in the audit and signals to regulators and customers that management does not govern AI.', 'ISO42001'),
  ('DR-ISO42001-C-01.3', 'Delta-Pack', 'Risiko bei Nichterfüllung: Ohne definierte Rollen ist niemand für Risikobewertung, Vorfallmeldung oder Modellfreigabe verantwortlich – im Ernstfall verweisen IT, Fachbereich und Datenschutz aufeinander. Klausel 5.3 und A.3.2 verlangen zugewiesene und kommunizierte Verantwortlichkeiten; die fehlende Zuweisung ist eine Nichtkonformität und führt praktisch dazu, dass gesetzliche Fristen (etwa nach AI Act Art. 73) mangels Zuständigkeit verstreichen.', 'Risk of non-compliance: Without defined roles nobody is responsible for risk assessment, incident reporting or model release – in an emergency IT, business and data protection point at each other. Clause 5.3 and A.3.2 require assigned and communicated responsibilities; the missing assignment is a non-conformity and in practice lets statutory deadlines (such as AI Act Art. 73) lapse for want of an owner.', 'ISO42001'),
  ('DR-ISO42001-C-01.4', 'Delta-Pack', 'Risiko bei Nichterfüllung: Werden interessierte Parteien (Betroffene, Betriebsrat, Aufsichtsbehörden, Kunden, Lieferanten) und ihre Erwartungen nicht erfasst, fehlen dem AIMS die Anforderungen, die es eigentlich erfüllen soll – regulatorische Vorgaben und Vertragspflichten werden erst nach einer Beschwerde entdeckt. Klausel 4.2 verlangt diese Analyse als Grundlage für Scope und Ziele; ohne sie ist die Kontextbestimmung unvollständig, und der Auditor bewertet das gesamte Managementsystem als unfundiert.', 'Risk of non-compliance: If interested parties (affected persons, works council, regulators, customers, suppliers) and their expectations are not captured, the AIMS lacks the very requirements it is meant to fulfil – regulatory and contractual obligations are discovered only after a complaint. Clause 4.2 requires this analysis as the basis for scope and objectives; without it the context determination is incomplete and the auditor rates the entire management system as unfounded.', 'ISO42001'),
  ('DR-ISO42001-C-02.1', 'Delta-Pack', 'Risiko bei Nichterfüllung: Ohne vollständiges Inventar (Zweck, Risikoklasse, Verantwortlicher, Datenquellen, Anbieter, Version usw.) weiß die Organisation nicht, welche KI-Systeme sie betreibt – die Klassifizierung nach AI Act Art. 6 und die Registrierung nach Art. 49 können systematisch nicht erfolgen. A.4.2 und A.6.2.7 verlangen die Erfassung von Ressourcen und Systemen; ein lückenhaftes Inventar ist eine Nichtkonformität und die häufigste Ursache dafür, dass Hochrisiko-Systeme erst von Behörden entdeckt werden.', 'Risk of non-compliance: Without a complete inventory (purpose, risk class, owner, data sources, vendor, version etc.) the organisation does not know which AI systems it operates – classification under AI Act Art. 6 and registration under Art. 49 cannot be done systematically. A.4.2 and A.6.2.7 require the recording of resources and systems; a patchy inventory is a non-conformity and the most common reason why high-risk systems are first discovered by authorities.', 'ISO42001'),
  ('DR-ISO42001-C-02.2', 'Delta-Pack', 'Risiko bei Nichterfüllung: Ohne Genehmigungsprozess kann jede Abteilung KI-Systeme einführen, bevor Risikoanalyse, Datenschutzprüfung und Klassifizierung erfolgt sind – der Fehler wird erst im Betrieb sichtbar. Klausel 8.1 und A.6.2.2–A.6.2.5 verlangen geplante, gesteuerte Lebenszyklusprozesse mit definierten Anforderungen und Verifizierung; ihr Fehlen ist eine Hauptabweichung und macht die Organisation für unbedachte Einführungen voll haftbar.', 'Risk of non-compliance: Without an approval process any department can roll out AI systems before risk analysis, privacy review and classification have taken place – the error surfaces only in operation. Clause 8.1 and A.6.2.2–A.6.2.5 require planned, controlled lifecycle processes with defined requirements and verification; their absence is a major non-conformity and leaves the organisation fully liable for ill-considered deployments.', 'ISO42001'),
  ('DR-ISO42001-C-02.3', 'Delta-Pack', 'Risiko bei Nichterfüllung: Ohne Dekommissionierungsprozess laufen abgelöste Modelle und ihre Endpunkte weiter, Trainingsdaten und Logs verbleiben ohne Löschkonzept, und alte Systeme treffen weiterhin Entscheidungen, für die niemand mehr zuständig ist. A.6.1.3 verlangt Prozesse für das Ende des Lebenszyklus; das Versäumnis erzeugt DSGVO-Löschverstöße, Sicherheitsrisiken durch vergessene Schnittstellen und ein Inventar, das nicht mehr stimmt.', 'Risk of non-compliance: Without a decommissioning process, retired models and their endpoints keep running, training data and logs remain without a deletion concept, and old systems continue making decisions for which nobody is responsible any more. A.6.1.3 requires processes for the end of the lifecycle; the omission produces GDPR deletion breaches, security risks from forgotten interfaces and an inventory that no longer reflects reality.', 'ISO42001'),
  ('DR-ISO42001-C-02.4', 'Delta-Pack', 'Risiko bei Nichterfüllung: Ein Inventar, das nicht quartalsweise abgeglichen wird, verliert binnen Monaten den Bezug zur Realität – neue SaaS-Funktionen mit KI, umgewidmete Modelle und stillgelegte Systeme fehlen. A.4.2 verlangt die Pflege der Ressourcendokumentation; ein veraltetes Inventar wird im Audit als unwirksame Kontrolle gewertet, und Berichte an Leitung oder Behörde beruhen auf falschen Zahlen.', 'Risk of non-compliance: An inventory that is not reconciled quarterly loses touch with reality within months – new SaaS features with embedded AI, repurposed models and retired systems are missing. A.4.2 requires the resource documentation to be maintained; an outdated inventory is rated as an ineffective control in the audit, and reports to management or the authority rest on wrong figures.', 'ISO42001'),
  ('DR-ISO42001-C-03.1', 'Delta-Pack', 'Risiko bei Nichterfüllung: Ohne messbare Ziele („100 % der Hochrisiko-Systeme mit FRIA bis Q2“, „Bias-Abweichung unter 5 %“) bleibt KI-Governance eine Absichtserklärung, deren Erreichung niemand feststellen kann. Klausel 6.2 verlangt messbare, überwachte Ziele mit Verantwortlichen und Terminen; das Fehlen ist eine Nichtkonformität, und der Management-Review nach 9.3 hat keine Grundlage zur Bewertung der Wirksamkeit.', 'Risk of non-compliance: Without measurable objectives (''100 % of high-risk systems with a FRIA by Q2'', ''bias deviation below 5 %'') AI governance remains a statement of intent whose achievement nobody can determine. Clause 6.2 requires measurable, monitored objectives with owners and deadlines; their absence is a non-conformity, and the management review under 9.3 has no basis for evaluating effectiveness.', 'ISO42001'),
  ('DR-ISO42001-C-03.2', 'Delta-Pack', 'Risiko bei Nichterfüllung: Ohne regelmäßig gemessene KPIs (Anteil klassifizierter Systeme, offene Findings, Vorfälle, Schulungsquote) erkennt die Leitung Verschlechterungen nicht, und Ressourcenentscheidungen beruhen auf Bauchgefühl. Klausel 9.1 verlangt die Festlegung, was wie und wann gemessen wird und wer die Ergebnisse auswertet; fehlende Messung entzieht der Bewertung der AIMS-Leistung jede Grundlage und wird im Audit als Nichtkonformität bewertet.', 'Risk of non-compliance: Without regularly measured KPIs (share of classified systems, open findings, incidents, training rate) management does not notice deterioration, and resource decisions rest on gut feeling. Clause 9.1 requires determining what is measured, how, when and who evaluates the results; missing measurement removes any basis for evaluating AIMS performance and is rated as a non-conformity in the audit.', 'ISO42001'),
  ('DR-ISO42001-C-03.3', 'Delta-Pack', 'Risiko bei Nichterfüllung: Ohne Management-Review mit KI-Agenda bleiben Auditergebnisse, Vorfälle und Ressourcenbedarf auf Fachebene stecken; die Leitung trifft keine Entscheidungen zu Verbesserungen und kann später nicht belegen, das AIMS gesteuert zu haben. Klausel 9.3 verlangt die Bewertung in geplanten Abständen mit definierten Eingaben und dokumentierten Ergebnissen; ihr Fehlen ist eine Hauptabweichung und im Haftungsfall ein zentrales Indiz für fehlende Leitungsverantwortung.', 'Risk of non-compliance: Without a management review with an AI agenda, audit results, incidents and resource needs get stuck at specialist level; leadership takes no improvement decisions and cannot later prove it governed the AIMS. Clause 9.3 requires review at planned intervals with defined inputs and documented outputs; its absence is a major non-conformity and, in a liability case, a key indicator of missing leadership responsibility.', 'ISO42001'),
  ('DR-ISO42001-C-03.4', 'Delta-Pack', 'Risiko bei Nichterfüllung: Ohne im Jahresbudget verankerte Ressourcen (Personal, Werkzeuge für Bias-Tests, externe Audits) bleiben Maßnahmen aus dem Risikomanagement unumgesetzt, weil sie „nicht eingeplant“ sind. Klausel 7.1 verlangt die Bereitstellung der erforderlichen Ressourcen für Aufbau und Aufrechterhaltung des AIMS; chronische Unterfinanzierung führt zu wiederkehrenden Nichtkonformitäten und entlarvt die KI-Politik als Lippenbekenntnis.', 'Risk of non-compliance: Without resources anchored in the annual budget (staff, bias-testing tools, external audits) risk-management measures remain unimplemented because they were ''not planned for''. Clause 7.1 requires provision of the resources needed to establish and maintain the AIMS; chronic underfunding leads to recurring non-conformities and exposes the AI policy as lip service.', 'ISO42001'),
  ('DR-ISO42001-C-04.1', 'Delta-Pack', 'Risiko bei Nichterfüllung: Ohne internes Auditprogramm werden Abweichungen erst vom externen Zertifizierer oder von einer Behörde gefunden – ohne Chance auf vorherige Korrektur. Klausel 9.2 verlangt geplante interne Audits mit definierter Häufigkeit, Methode und unabhängigen Auditoren; ihr Fehlen ist eine Hauptabweichung, die die Zertifizierung verhindert oder zur Aussetzung des Zertifikats führt.', 'Risk of non-compliance: Without an internal audit programme, deviations are found first by the external certifier or an authority – with no chance of prior correction. Clause 9.2 requires planned internal audits with defined frequency, method and independent auditors; their absence is a major non-conformity that prevents certification or leads to suspension of the certificate.', 'ISO42001'),
  ('DR-ISO42001-C-04.2', 'Delta-Pack', 'Risiko bei Nichterfüllung: Audit-Feststellungen, die nicht als Korrekturmaßnahmen mit Ursache, Verantwortlichem und Termin erfasst werden, versanden; im Folgeaudit taucht derselbe Befund wieder auf und wird zur Wiederholungsabweichung hochgestuft. Klausel 10.2 verlangt Reaktion, Ursachenanalyse, Maßnahme und Wirksamkeitsprüfung; das Fehlen zeigt dem Auditor, dass das AIMS keine Lernschleife besitzt.', 'Risk of non-compliance: Audit findings that are not captured as corrective actions with root cause, owner and deadline fizzle out; the same finding reappears in the follow-up audit and is escalated to a repeat non-conformity. Clause 10.2 requires reaction, root-cause analysis, action and effectiveness check; their absence shows the auditor that the AIMS has no learning loop.', 'ISO42001'),
  ('DR-ISO42001-C-04.3', 'Delta-Pack', 'Risiko bei Nichterfüllung: Ohne Lessons-Learned-Prozess bleibt das Wissen über einen KI-Vorfall (etwa ein Prompt-Leak oder eine diskriminierende Empfehlung) beim beteiligten Team; andere Systeme mit derselben Schwachstelle werden nicht geprüft. Klausel 10.1/10.2 und A.8.4 verlangen Verbesserung aus Vorfällen und die Weitergabe der Erkenntnisse; ihr Fehlen führt zu wiederholten Vorfällen gleicher Art, die Behörden als systematisches Versagen werten.', 'Risk of non-compliance: Without a lessons-learned process, knowledge about an AI incident (a prompt leak, a discriminatory recommendation) stays with the team involved; other systems with the same weakness are never checked. Clause 10.1/10.2 and A.8.4 require improvement from incidents and sharing of the insights; their absence leads to repeated incidents of the same kind, which authorities treat as systemic failure.', 'ISO42001'),
  ('DR-ISO42001-C-04.4', 'Delta-Pack', 'Risiko bei Nichterfüllung: Werden Verbesserungsvorschläge von Anwendern, Aufsichtspersonen und Betroffenen nicht systematisch erfasst, gehen frühe Warnsignale (steigende Overrides, unverständliche Ausgaben) verloren, bevor sie zum Vorfall werden. Klausel 10.1 verlangt die Bestimmung und Umsetzung von Verbesserungsmöglichkeiten; ohne Erfassungsmechanismus kann die fortlaufende Verbesserung nicht nachgewiesen werden, und das AIMS wird als statisch beanstandet.', 'Risk of non-compliance: If improvement suggestions from users, oversight staff and affected persons are not captured systematically, early warning signals (rising overrides, unintelligible outputs) are lost before they turn into incidents. Clause 10.1 requires determining and implementing improvement opportunities; without a capture mechanism continual improvement cannot be demonstrated, and the AIMS is flagged as static.', 'ISO42001'),
  ('DR-ISO42001-C-05.1', 'Delta-Pack', 'Risiko bei Nichterfüllung: Ohne KI-Auswirkungsabschätzung sind die Folgen für Einzelpersonen, Gruppen und Gesellschaft (Fehlentscheidungen, Ausgrenzung, Fehlinformation) nicht bewertet, und Maßnahmen wirken auf Verdacht. Klausel 6.1.4/8.4 und A.5.2–A.5.5 verlangen die dokumentierte Abschätzung samt Folgen für Betroffene; das Fehlen ist eine Hauptabweichung und lässt gleichzeitig die Pflichten aus AI Act Art. 27 (FRIA) und DSGVO Art. 35 (DSFA) unerfüllt.', 'Risk of non-compliance: Without an AI impact assessment the consequences for individuals, groups and society (wrong decisions, exclusion, misinformation) are unevaluated, and measures are applied on suspicion. Clause 6.1.4/8.4 and A.5.2–A.5.5 require a documented assessment including consequences for affected persons; its absence is a major non-conformity and simultaneously leaves the duties under AI Act Art. 27 (FRIA) and GDPR Art. 35 (DPIA) unfulfilled.', 'ISO42001'),
  ('DR-ISO42001-C-05.2', 'Delta-Pack', 'Risiko bei Nichterfüllung: Ohne definierte ethische Grundsätze (Fairness, Erklärbarkeit, menschliche Kontrolle) fehlt der Maßstab, an dem Entwickler und Einkäufer Grenzfälle entscheiden – ob eine Emotionserkennung oder eine Mitarbeiterbewertung zulässig ist, entscheidet dann der Zufall. A.2.2 und A.6.1.2 verlangen, dass die KI-Politik solche Ziele festlegt und die Entwicklungsprozesse sie umsetzen; ihr Fehlen wird als unvollständige Politik beanstandet und liefert im Krisenfall die Schlagzeile „Unternehmen ohne KI-Ethik“.', 'Risk of non-compliance: Without defined ethical principles (fairness, explainability, human control) there is no yardstick by which developers and buyers decide borderline cases – whether an emotion-recognition feature or an employee rating is acceptable is then left to chance. A.2.2 and A.6.1.2 require the AI policy to set such objectives and development processes to implement them; their absence is flagged as an incomplete policy and, in a crisis, delivers the headline ''company without AI ethics''.', 'ISO42001'),
  ('DR-ISO42001-C-05.3', 'Delta-Pack', 'Risiko bei Nichterfüllung: Wird der Betriebsrat bei KI-Systemen, die Leistung oder Verhalten von Beschäftigten erfassen können, nicht beteiligt, ist die Einführung nach § 87 Abs. 1 Nr. 6 BetrVG mitbestimmungswidrig – der Betriebsrat kann per einstweiliger Verfügung die Abschaltung erzwingen, und Kündigungen auf Basis der Daten sind unverwertbar. AI Act Art. 26 Abs. 7 verpflichtet Arbeitgeber zusätzlich, Arbeitnehmervertreter vor Inbetriebnahme eines Hochrisiko-Systems zu informieren; das Versäumnis ist ein Betreiberverstoß nach Art. 99 Abs. 4.', 'Risk of non-compliance: If the works council is not involved for AI systems capable of capturing employee performance or behaviour, the rollout violates co-determination under Section 87(1) No. 6 of the German Works Constitution Act – the works council can force a shutdown by interim injunction, and dismissals based on the data are inadmissible. AI Act Art. 26(7) additionally obliges employers to inform worker representatives before putting a high-risk system into service; the omission is a deployer breach under Art. 99(4).', 'ISO42001'),
  ('DR-ISO42001-C-05.4', 'Delta-Pack', 'Risiko bei Nichterfüllung: Ohne externe Perspektive bewerten Hochrisiko-Systeme nur die Teams, die sie gebaut oder beschafft haben – blinde Flecken bei Diskriminierung, Zumutbarkeit und gesellschaftlicher Wirkung bleiben bestehen. NIST GOVERN 5.2 und MEASURE 1.2 empfehlen unabhängige Bewertung und Feedback-Mechanismen; fehlt sie, kann die Organisation bei einem Vorfall nicht belegen, mehr als das Minimum getan zu haben, und verliert den Vertrauensvorsprung gegenüber Kunden und Aufsicht.', 'Risk of non-compliance: Without an external perspective, high-risk systems are evaluated only by the teams that built or procured them – blind spots on discrimination, reasonableness and societal impact persist. NIST GOVERN 5.2 and MEASURE 1.2 recommend independent evaluation and feedback mechanisms; without them the organisation cannot show after an incident that it did more than the minimum and loses its trust advantage with customers and regulators.', 'ISO42001'),
  ('DR-ISO42001-C-05.5', 'Delta-Pack', 'Risiko bei Nichterfüllung: Ohne Eskalationsweg für ethische Bedenken bleiben Hinweise von Mitarbeitern („das Modell benachteiligt ältere Bewerber“) beim Vorgesetzten hängen oder werden gar nicht geäußert; der Vorfall eskaliert stattdessen über Hinweisgeberkanäle oder die Presse. A.3.3 verlangt einen Prozess zur Meldung von Bedenken; sein Fehlen ist eine Nichtkonformität und kollidiert mit dem Hinweisgeberschutzgesetz, wenn Meldungen ohne Reaktion bleiben.', 'Risk of non-compliance: Without an escalation route for ethical concerns, employee warnings (''the model disadvantages older applicants'') stall with the line manager or are never raised; the issue escalates instead via whistleblower channels or the press. A.3.3 requires a process for reporting concerns; its absence is a non-conformity and collides with the German Whistleblower Protection Act when reports go unanswered.', 'ISO42001'),
  ('DR-ISO42001-C-06.1', 'Delta-Pack', 'Risiko bei Nichterfüllung: Ohne Kompetenzprofile ist nicht definiert, was ein Aufsichtsverantwortlicher, ein Modellentwickler oder ein Einkäufer über KI-Risiken wissen muss – Schulungen bleiben generisch und Lücken unerkannt. Klausel 7.2 und A.4.6 verlangen die Bestimmung der erforderlichen Kompetenz und ihren Nachweis; ohne Profil kann weder die ISO-Anforderung noch die KI-Kompetenzpflicht nach AI Act Art. 4 belegt werden.', 'Risk of non-compliance: Without competence profiles it is undefined what an oversight owner, a model developer or a buyer must know about AI risks – training stays generic and gaps go unnoticed. Clause 7.2 and A.4.6 require determining the necessary competence and evidencing it; without a profile neither the ISO requirement nor the AI literacy duty under AI Act Art. 4 can be demonstrated.', 'ISO42001'),
  ('DR-ISO42001-C-06.2', 'Delta-Pack', 'Risiko bei Nichterfüllung: Ohne zentrale Schulungsnachweise kann bei einer Behördenanfrage oder nach einem Vorfall nicht belegt werden, dass die handelnde Person geschult war – das Unternehmen haftet für Organisationsverschulden. Klausel 7.2 und 7.3 verlangen dokumentierte Kompetenz- und Bewusstseinsnachweise; die Auswertbarkeit ist zudem Voraussetzung, um die Schulungsquote als KPI nach 9.1 zu berichten und die Kompetenzpflicht nach AI Act Art. 4 nachzuweisen.', 'Risk of non-compliance: Without central training records it cannot be proven after an authority request or an incident that the acting person was trained – the company is liable for organisational fault. Clauses 7.2 and 7.3 require documented evidence of competence and awareness; analysability is also the precondition for reporting the training rate as a KPI under 9.1 and for evidencing the AI literacy duty under AI Act Art. 4.', 'ISO42001'),
  ('DR-ISO42001-C-06.3', 'Delta-Pack', 'Risiko bei Nichterfüllung: Ohne Kriterien, wann externe Expertise (Rechtsberatung zur Klassifizierung, technischer Bias-Audit, notifizierte Stelle) eingeholt werden muss, entscheiden Teams komplexe Fragen selbst und liegen bei Grenzfällen falsch – mit voller Verantwortung des Unternehmens. Klausel 7.2 verweist in der Anmerkung auf die Beschaffung fehlender Kompetenz; fehlt der Auslöser dafür, entsteht eine Kompetenzlücke, die im Audit als Nichtkonformität und im Schadensfall als Fahrlässigkeit bewertet wird.', 'Risk of non-compliance: Without criteria for when external expertise (legal advice on classification, technical bias audit, notified body) must be brought in, teams decide complex questions themselves and get borderline cases wrong – with full responsibility resting on the company. The note to Clause 7.2 points to acquiring missing competence; without a trigger for it, a competence gap arises that is rated as a non-conformity in the audit and as negligence when harm occurs.', 'ISO42001'),
  ('DR-ISO42001-C-07.1', 'Delta-Pack', 'Risiko bei Nichterfüllung: Werden Kunden und Betroffene nicht darüber informiert, wo KI eingesetzt wird (Chatbot, automatisierte Vorentscheidung, generierte Inhalte), erfahren sie es durch Zufall oder Medien – und werten es als Täuschung. Klausel 7.4 sowie A.8.2/A.8.5 verlangen geplante externe Kommunikation und Nutzerinformation; parallel verletzt das Schweigen die Transparenzpflichten des AI Act Art. 50 (Art. 99 Abs. 4, bis 15 Mio. €/3 %) und der DSGVO Art. 13.', 'Risk of non-compliance: If customers and affected persons are not told where AI is used (chatbot, automated pre-decision, generated content), they find out by chance or through the media – and read it as deception. Clause 7.4 and A.8.2/A.8.5 require planned external communication and user information; in parallel, the silence breaches the transparency duties of AI Act Art. 50 (Art. 99(4), up to EUR 15 million/3 %) and GDPR Art. 13.', 'ISO42001'),
  ('DR-ISO42001-C-07.2', 'Delta-Pack', 'Risiko bei Nichterfüllung: Ohne interne KI-Nutzungsrichtlinie geben Mitarbeiter Kundendaten, Quellcode und Vertragsentwürfe in öffentliche Chatbots ein, und die Organisation erfährt vom Abfluss erst, wenn die Daten in fremden Antworten auftauchen. A.9.2/A.9.3 und A.2.2 verlangen Prozesse für die verantwortungsvolle Nutzung und deren Kommunikation; das Fehlen ist eine Nichtkonformität und die häufigste Ursache für DSGVO-Meldepflichten und Geheimnisverlust nach GeschGehG.', 'Risk of non-compliance: Without an internal AI usage policy, employees paste customer data, source code and draft contracts into public chatbots, and the organisation learns of the leak only when the data appears in someone else''s answers. A.9.2/A.9.3 and A.2.2 require processes for responsible use and their communication; the absence is a non-conformity and the most common trigger of GDPR breach notifications and loss of trade-secret protection.', 'ISO42001'),
  ('DR-ISO42001-C-07.3', 'Delta-Pack', 'Risiko bei Nichterfüllung: Bleibt ein KI-Vorfall auf das betroffene Team beschränkt, wissen andere Abteilungen nicht, dass derselbe Anbieter, dasselbe Modell oder dieselbe Prompt-Technik bei ihnen ebenfalls im Einsatz ist – der Vorfall wiederholt sich an anderer Stelle. A.8.4 verlangt die Kommunikation von Vorfällen an relevante interessierte Parteien; ihr Fehlen wird als unwirksames Vorfallmanagement gewertet und verhindert die Verbesserung nach Klausel 10.', 'Risk of non-compliance: If an AI incident stays confined to the affected team, other departments do not know that the same vendor, model or prompting technique is in use with them too – the incident repeats elsewhere. A.8.4 requires communication of incidents to relevant interested parties; its absence is rated as ineffective incident management and blocks improvement under Clause 10.', 'ISO42001'),
  ('DR-ISO42001-C-07.4', 'Delta-Pack', 'Risiko bei Nichterfüllung: Ohne Beschwerdeweg haben Betroffene einer KI-Entscheidung keine Möglichkeit, Fehler anzuzeigen – sie wenden sich direkt an Datenschutzbehörde, Verbraucherzentrale oder Gericht, und die Organisation verliert die Chance auf stille Korrektur. A.8.3 und A.3.3 verlangen Mechanismen für Eingaben Betroffener; parallel fordert AI Act Art. 86 ein Recht auf Erläuterung und Art. 27 Abs. 1 lit. f einen Beschwerdemechanismus als Teil der FRIA, sodass das Versäumnis auch gesetzlich sanktionsbewehrt ist.', 'Risk of non-compliance: Without a complaint channel, persons affected by an AI decision have no way to flag errors – they go straight to the data protection authority, consumer body or court, and the organisation loses the chance of a quiet correction. A.8.3 and A.3.3 require mechanisms for input from affected persons; in parallel, AI Act Art. 86 grants a right to explanation and Art. 27(1)(f) requires a complaint mechanism as part of the FRIA, so the omission is also legally sanctionable.', 'ISO42001'),
  ('DR-ISO42001-C-08.1', 'Delta-Pack', 'Risiko bei Nichterfüllung: Ohne strukturierten Beschaffungsprozess werden KI-Dienste nach Funktion und Preis gekauft, während Fragen zu Trainingsdaten, Datenverarbeitung außerhalb der EU, Modellupdates und Haftung offenbleiben – und nach Vertragsschluss nicht mehr verhandelbar sind. A.10.3 verlangt die Sicherstellung, dass Lieferanten mit dem KI-Ansatz der Organisation übereinstimmen; das Versäumnis ist eine Nichtkonformität, und die Organisation übernimmt als Betreiber Pflichten, die der Anbieter vertraglich nie zugesichert hat.', 'Risk of non-compliance: Without a structured procurement process, AI services are bought on features and price while questions about training data, processing outside the EU, model updates and liability remain open – and are no longer negotiable after signature. A.10.3 requires ensuring that suppliers align with the organisation''s AI approach; the omission is a non-conformity, and the organisation takes on deployer duties that the vendor never contractually supported.', 'ISO42001'),
  ('DR-ISO42001-C-08.2', 'Delta-Pack', 'Risiko bei Nichterfüllung: Ohne AGB-Analyse bleibt unbemerkt, dass ein KI-Dienst Eingaben zum Training verwendet, die Haftung vollständig ausschließt, Daten in Drittländer überträgt oder Funktionen jederzeit ändern darf. A.10.2/A.10.3 verlangen die Zuweisung von Verantwortlichkeiten und die Prüfung der Lieferanten; die Folge des Versäumnisses sind DSGVO-Verstöße bei Drittlandtransfers, Geschäftsgeheimnisverlust und ein Anbieter, der bei einem Vorfall vertraglich nichts schuldet.', 'Risk of non-compliance: Without a terms-of-service analysis it goes unnoticed that an AI service uses inputs for training, excludes liability entirely, transfers data to third countries or may change functions at any time. A.10.2/A.10.3 require allocation of responsibilities and review of suppliers; the consequences of the omission are GDPR breaches on third-country transfers, loss of trade secrets and a vendor that owes nothing contractually when an incident occurs.', 'ISO42001'),
  ('DR-ISO42001-C-08.3', 'Delta-Pack', 'Risiko bei Nichterfüllung: Kennt die Organisation die Subunternehmer ihrer KI-Anbieter nicht (Basismodell-Anbieter, Hosting, Annotationsdienstleister), weiß sie nicht, wo ihre Daten tatsächlich verarbeitet werden und welche Modellabhängigkeit im Hintergrund steht. A.10.3 verlangt die Steuerung der gesamten Lieferkette; das Versäumnis erzeugt unbekannte Drittlandtransfers (DSGVO Art. 28 Abs. 2, Art. 44), unkontrollierte Modellwechsel und Ausfallrisiken bei Abkündigung eines vorgelagerten Anbieters.', 'Risk of non-compliance: If the organisation does not know its AI vendors'' subcontractors (base-model provider, hosting, annotation services), it does not know where its data is actually processed or which model dependency sits behind the service. A.10.3 requires control of the entire supply chain; the omission produces unknown third-country transfers (GDPR Art. 28(2), Art. 44), uncontrolled model swaps and outage risks when an upstream provider discontinues its service.', 'ISO42001'),
  ('DR-NAIRMF-G1.1', 'Delta-Pack', 'Risiko bei Nichterfüllung: Ohne systematische Erfassung der rechtlichen Anforderungen (AI Act, DSGVO, AGG, BetrVG, sektorale Vorgaben) werden Pflichten erst entdeckt, wenn Fristen wie die Hochrisikopflichten des AI Act (Anhang III ab 2. Dezember 2027, Anhang I ab 2. August 2028) bereits laufen. GOVERN 1.1 verlangt, dass rechtliche Anforderungen verstanden, verwaltet und dokumentiert sind; fehlt die Rechtsmatrix, lässt sich gegenüber Behörden und Auditoren nicht nachweisen, dass Compliance geplant und nicht zufällig war.', 'Risk of non-compliance: Without a systematic register of legal requirements (AI Act, GDPR, equal-treatment law, works-council law, sector rules), obligations are discovered only when deadlines such as the AI Act high-risk duties (Annex III from 2 December 2027, Annex I from 2 August 2028) are already running. GOVERN 1.1 requires legal requirements to be understood, managed and documented; without the legal matrix it cannot be demonstrated to authorities and auditors that compliance was planned rather than accidental.', 'NIST_AI_RMF'),
  ('DR-NAIRMF-G1.2', 'Delta-Pack', 'Risiko bei Nichterfüllung: Bleiben die Merkmale vertrauenswürdiger KI (Validität, Sicherheit, Transparenz, Fairness, Datenschutz) außerhalb von Richtlinien und Prozessen, hängen sie vom Engagement einzelner Entwickler ab und verschwinden unter Zeitdruck. GOVERN 1.2 verlangt ihre Integration in die organisatorischen Policies; ohne diese Verankerung entstehen Systeme, die technisch funktionieren, aber die Fairness- und Transparenzanforderungen des AI Act (Art. 10, 13) verfehlen, und die Organisation kann ihre Grundsätze nicht nachweisbar belegen.', 'Risk of non-compliance: If the characteristics of trustworthy AI (validity, safety, transparency, fairness, privacy) stay outside policies and processes, they depend on the commitment of individual developers and vanish under time pressure. GOVERN 1.2 requires their integration into organisational policies; without this anchoring, systems emerge that work technically but miss the fairness and transparency requirements of the AI Act (Art. 10, 13), and the organisation cannot evidence its principles.', 'NIST_AI_RMF'),
  ('DR-NAIRMF-G2.1', 'Delta-Pack', 'Risiko bei Nichterfüllung: Sind Rollen und Befugnisse für KI-Risiken nicht zugewiesen, kann niemand ein System stoppen, einen Vorfall melden oder eine Freigabe verweigern – Entscheidungen fallen faktisch beim Entwicklungsteam ohne Risikomandat. GOVERN 2.1 verlangt dokumentierte Rollen, Verantwortlichkeiten und Kommunikationswege; ihr Fehlen wird im Audit als fehlende Nachweisbarkeit gewertet und führt operativ dazu, dass gesetzliche Funktionen (etwa die Aufsichtsperson nach AI Act Art. 26 Abs. 2) unbesetzt bleiben.', 'Risk of non-compliance: If roles and authorities for AI risks are not assigned, nobody can stop a system, report an incident or refuse a release – decisions are effectively taken by the development team without a risk mandate. GOVERN 2.1 requires documented roles, responsibilities and lines of communication; their absence is rated in an audit as lack of accountability and operationally leaves statutory functions (such as the oversight person under AI Act Art. 26(2)) unfilled.', 'NIST_AI_RMF'),
  ('DR-NAIRMF-G3.1', 'Delta-Pack', 'Risiko bei Nichterfüllung: Homogene Teams ohne KI-Risiko-Schulung übersehen systematisch die Auswirkungen auf Gruppen, denen sie nicht angehören – Bias wird erst von Betroffenen entdeckt. GOVERN 3.1 und 2.2 verlangen Diversität, Kompetenz und Schulung als Teil des Risikomanagements; fehlen die Nachweise, ist auch die KI-Kompetenzpflicht nach AI Act Art. 4 nicht belegbar, und Diskriminierungsvorwürfe treffen eine Organisation, die nachweislich nichts zur Vorbeugung getan hat.', 'Risk of non-compliance: Homogeneous teams without AI-risk training systematically overlook the effects on groups they do not belong to – bias is discovered first by those affected. GOVERN 3.1 and 2.2 require diversity, competence and training as part of risk management; without the records, the AI literacy duty under AI Act Art. 4 cannot be evidenced either, and discrimination allegations hit an organisation that demonstrably did nothing to prevent them.', 'NIST_AI_RMF'),
  ('DR-NAIRMF-G4.1', 'Delta-Pack', 'Risiko bei Nichterfüllung: In einer Kultur, in der Bedenken zu KI-Systemen als Bremse gelten, melden Mitarbeiter auffällige Ausgaben nicht – der Vorfall wird erst öffentlich, wenn Betroffene ihn melden. GOVERN 4.1 verlangt eine Kultur, die kritische Prüfung und Meldung fördert; fehlt sie, bleiben Beinahe-Vorfälle unsichtbar, und die Organisation kann bei einer Untersuchung nicht zeigen, dass ihre Risikoprozesse in der Praxis genutzt werden.', 'Risk of non-compliance: In a culture where concerns about AI systems are seen as obstruction, staff do not report suspicious outputs – the incident becomes public only when affected persons report it. GOVERN 4.1 requires a culture that encourages critical examination and reporting; without it, near misses stay invisible and the organisation cannot show during an investigation that its risk processes are actually used in practice.', 'NIST_AI_RMF'),
  ('DR-NAIRMF-G5.1', 'Delta-Pack', 'Risiko bei Nichterfüllung: Ohne Einbindung von Betroffenen und Feedback-Kanäle erfährt die Organisation nicht, wie ihre Systeme tatsächlich wirken – Fehlklassifikationen, unverständliche Erklärungen und Ausgrenzungseffekte bleiben statistisch unsichtbar. GOVERN 5.1/5.2 verlangen Mechanismen für Rückmeldung und Beschwerde; fehlen sie, entfallen die Frühwarnsignale, und Beschwerden landen unmittelbar bei Aufsichtsbehörden, wo sie als Beleg fehlender Betroffenenrechte (AI Act Art. 86) dienen.', 'Risk of non-compliance: Without engaging affected persons and without feedback channels, the organisation never learns how its systems actually perform – misclassifications, unintelligible explanations and exclusion effects remain statistically invisible. GOVERN 5.1/5.2 require mechanisms for feedback and complaint; without them the early-warning signals are lost, and complaints land directly with regulators, where they serve as evidence of missing rights for affected persons (AI Act Art. 86).', 'NIST_AI_RMF'),
  ('DR-NAIRMF-G6.1', 'Delta-Pack', 'Risiko bei Nichterfüllung: Ohne Policies und SLAs für KI-Lieferanten kann ein Anbieter unangekündigt das Modell wechseln, Trainingsdaten aus Kundeneingaben ziehen oder den Dienst einstellen – die Organisation trägt die Folgen ohne vertraglichen Hebel. GOVERN 6.1/6.2 verlangen die Steuerung von Drittanbieterrisiken und Notfallpläne für deren Ausfall; das Versäumnis wird zur Haftungsfalle, wenn der Betreiber nach AI Act Art. 26 Pflichten erfüllen muss, die der Anbieter nicht unterstützt.', 'Risk of non-compliance: Without policies and SLAs for AI suppliers, a vendor can swap the model unannounced, harvest training data from customer inputs or discontinue the service – the organisation bears the consequences without contractual leverage. GOVERN 6.1/6.2 require managing third-party risks and contingency plans for their failure; the omission becomes a liability trap when the deployer must fulfil duties under AI Act Art. 26 that the vendor does not support.', 'NIST_AI_RMF'),
  ('DR-NAIRMF-M1.1', 'Delta-Pack', 'Risiko bei Nichterfüllung: Ohne dokumentierten Einsatzkontext (Zweck, Nutzergruppen, Umgebung, Ausschlüsse) ist jede Risikobewertung ohne Bezugsrahmen – dasselbe Modell ist im Marketing harmlos und in der Personalauswahl hochriskant. MAP 1.1 verlangt die Kontextbestimmung als Ausgangspunkt; fehlt sie, sind die Klassifizierung nach AI Act Art. 6 und die Zweckbindung nach Anhang IV nicht belegbar, und schleichende Zweckänderungen bleiben unerkannt.', 'Risk of non-compliance: Without a documented deployment context (purpose, user groups, environment, exclusions) every risk assessment lacks a frame of reference – the same model is harmless in marketing and high-risk in recruitment. MAP 1.1 requires context determination as the starting point; without it, classification under AI Act Art. 6 and purpose limitation under Annex IV cannot be evidenced, and gradual purpose changes go unnoticed.', 'NIST_AI_RMF'),
  ('DR-NAIRMF-M1.2', 'Delta-Pack', 'Risiko bei Nichterfüllung: Wird der Kontext nur von Technikern bestimmt, fehlen rechtliche, fachliche und Betroffenenperspektiven – der Datenschutzbeauftragte erfährt von der Datenverarbeitung nach dem Go-live, die Fachabteilung von den Modellgrenzen bei der ersten Fehlentscheidung. MAP 1.2 verlangt interdisziplinäre Teams für die Kontextanalyse; ohne sie werden Risiken systematisch unterschätzt, und der Nachweis einer sorgfältigen Bewertung fehlt.', 'Risk of non-compliance: If the context is determined by technicians alone, legal, domain and affected-person perspectives are missing – the data protection officer learns of the processing after go-live, the business unit of the model''s limits at the first wrong decision. MAP 1.2 requires interdisciplinary teams for context analysis; without them risks are systematically underestimated and the evidence of a diligent assessment is lacking.', 'NIST_AI_RMF'),
  ('DR-NAIRMF-M2.1', 'Delta-Pack', 'Risiko bei Nichterfüllung: Ohne Kategorisierung nach Aufgabe, Methode und Autonomiegrad werden ein regelbasierter Assistent und ein vollautomatisch entscheidendes Deep-Learning-Modell mit denselben Kontrollen behandelt – das eine überreguliert, das andere unterkontrolliert. MAP 2.1 verlangt diese Einordnung als Grundlage für Risikoprofil und Aufsichtstiefe; fehlt sie, ist auch die Frage nach automatisierter Einzelentscheidung (DSGVO Art. 22) und Hochrisiko-Einstufung (AI Act Anhang III) nicht beantwortbar.', 'Risk of non-compliance: Without categorisation by task, method and degree of autonomy, a rule-based assistant and a fully automated deep-learning decision model are handled with the same controls – one over-regulated, the other under-controlled. MAP 2.1 requires this categorisation as the basis for risk profile and depth of oversight; without it, the questions of automated individual decision-making (GDPR Art. 22) and high-risk classification (AI Act Annex III) cannot be answered either.', 'NIST_AI_RMF'),
  ('DR-NAIRMF-M3.1', 'Delta-Pack', 'Risiko bei Nichterfüllung: Werden Nutzen und Fähigkeiten überschätzt („das Modell erkennt Betrug zuverlässig“), wird das System mit zu viel Vertrauen und zu wenig Aufsicht eingesetzt, und Kosten-Nutzen-Entscheidungen beruhen auf den Marketingversprechen des Anbieters. MAP 3.1/3.2 verlangen eine realistische Bewertung von Nutzen und Grenzen einschließlich des Vergleichs mit Alternativen; ohne sie ist die Verhältnismäßigkeit des Einsatzes – Grundlage jeder FRIA und DSFA – nicht belegbar.', 'Risk of non-compliance: If benefits and capabilities are overestimated (''the model reliably detects fraud''), the system is deployed with too much trust and too little oversight, and cost-benefit decisions rest on the vendor''s marketing promises. MAP 3.1/3.2 require a realistic assessment of benefits and limits including comparison with alternatives; without it, the proportionality of the deployment – the foundation of every FRIA and DPIA – cannot be evidenced.', 'NIST_AI_RMF'),
  ('DR-NAIRMF-M4.1', 'Delta-Pack', 'Risiko bei Nichterfüllung: Werden Risiken aus eingebetteten Komponenten (Basismodelle, Bibliotheken, Datensätze Dritter) und Schäden für Unbeteiligte nicht identifiziert, übernimmt die Organisation fremde Schwachstellen und Verzerrungen, ohne sie zu kennen. MAP 4.1 verlangt die Bewertung von Drittanbieterrisiken und rechtlichen Folgen; fehlt sie, ist die Risikoanalyse nach AI Act Art. 9 unvollständig, und die Haftung für Schäden aus zugekauften Komponenten trifft die Organisation, weil sie diese ungeprüft integriert hat.', 'Risk of non-compliance: If risks from embedded components (base models, libraries, third-party datasets) and harms to third parties are not identified, the organisation inherits foreign vulnerabilities and biases without knowing them. MAP 4.1 requires assessment of third-party risks and legal consequences; without it the risk analysis under AI Act Art. 9 is incomplete, and liability for harm from purchased components falls on the organisation because it integrated them unexamined.', 'NIST_AI_RMF'),
  ('DR-NAIRMF-M5.1', 'Delta-Pack', 'Risiko bei Nichterfüllung: Ohne Abschätzung der Auswirkungen auf Einzelpersonen, Gruppen und Gesellschaft bleiben kumulative Effekte unbeachtet – einzeln vertretbare Entscheidungen führen in Summe zum Ausschluss ganzer Bevölkerungsgruppen von Krediten, Jobs oder Leistungen. MAP 5.1 verlangt die Bewertung von Wahrscheinlichkeit und Ausmaß solcher Auswirkungen; fehlt sie, ist weder die FRIA nach AI Act Art. 27 noch die Auswirkungsabschätzung nach ISO 42001 (A.5) erfüllbar, und die Organisation kann gesellschaftliche Schäden nicht als bedacht nachweisen.', 'Risk of non-compliance: Without assessing impacts on individuals, groups and society, cumulative effects go unconsidered – individually defensible decisions add up to the exclusion of entire population groups from credit, jobs or benefits. MAP 5.1 requires assessing the likelihood and magnitude of such impacts; without it neither the FRIA under AI Act Art. 27 nor the ISO 42001 impact assessment (A.5) can be satisfied, and the organisation cannot show that societal harm was ever considered.', 'NIST_AI_RMF'),
  ('DR-NAIRMF-Ma1.1', 'Delta-Pack', 'Risiko bei Nichterfüllung: Ohne Priorisierung fließen die Ressourcen in leicht behebbare, aber unbedeutende Risiken, während die gravierenden (etwa unerkannte Diskriminierung in Entscheidungen mit Rechtswirkung) unbehandelt bleiben. MANAGE 1.1–1.3 verlangen dokumentierte Entscheidungen, ob ein Risiko vermieden, gemindert, übertragen oder akzeptiert wird; ohne diese Entscheidungen fehlt der Nachweis, dass die Leitung Restrisiken bewusst getragen hat.', 'Risk of non-compliance: Without prioritisation, resources flow into easily fixed but insignificant risks while the serious ones (such as undetected discrimination in decisions with legal effect) remain untreated. MANAGE 1.1–1.3 require documented decisions on whether a risk is avoided, mitigated, transferred or accepted; without those decisions there is no evidence that leadership knowingly carried the residual risks.', 'NIST_AI_RMF'),
  ('DR-NAIRMF-Ma2.1', 'Delta-Pack', 'Risiko bei Nichterfüllung: Bleiben geplante Maßnahmen (Bias-Korrektur, Erklärungsfunktion, Nutzungsbeschränkung) unumgesetzt, existiert das Risikomanagement nur als Dokument – die Schäden treten ein, obwohl sie erkannt und Gegenmaßnahmen beschlossen waren. MANAGE 2.1/2.2 verlangen die tatsächliche Umsetzung und Wirksamkeitsprüfung; im Schadensfall ist das dokumentierte, aber nicht umgesetzte Vorhaben der belastendste Beweis für Fahrlässigkeit.', 'Risk of non-compliance: If planned measures (bias correction, explanation feature, usage restriction) remain unimplemented, risk management exists only as a document – the harm occurs even though it was recognised and countermeasures had been decided. MANAGE 2.1/2.2 require actual implementation and effectiveness checking; when harm occurs, the documented but unimplemented plan is the most damaging evidence of negligence.', 'NIST_AI_RMF'),
  ('DR-NAIRMF-Ma2.3', 'Delta-Pack', 'Risiko bei Nichterfüllung: Ohne Verfahren zur schnellen Deaktivierung läuft ein System, das sich als unsicher erwiesen hat (Datenleck, massenhafte Fehlentscheidung, manipuliertes Modell), weiter, weil niemand weiß, welche Prozesse davon abhängen und wer die Abschaltung anordnen darf. MANAGE 2.4 verlangt Mechanismen zum Ersetzen, Deaktivieren oder Abschalten; fehlen sie, verlängert sich jeder Vorfall um Stunden bis Tage, was die Zahl der Betroffenen und die Bußgeldbemessung nach AI Act Art. 99 Abs. 7 (Dauer des Verstoßes) unmittelbar erhöht.', 'Risk of non-compliance: Without a rapid deactivation procedure, a system that has proven unsafe (data leak, mass wrong decisions, manipulated model) keeps running because nobody knows which processes depend on it or who may order the shutdown. MANAGE 2.4 requires mechanisms to supersede, disengage or deactivate; without them every incident is prolonged by hours to days, which directly increases the number of affected persons and the fine calculation under AI Act Art. 99(7) (duration of the infringement).', 'NIST_AI_RMF'),
  ('DR-NAIRMF-Ma3.1', 'Delta-Pack', 'Risiko bei Nichterfüllung: Ohne laufende Überwachung der KI-Lieferanten bleiben Modellwechsel, geänderte Nutzungsbedingungen, Sicherheitsvorfälle beim Anbieter und Abkündigungen unbemerkt, bis sie im eigenen Betrieb Wirkung zeigen. MANAGE 3.1 verlangt die regelmäßige Überwachung und Behandlung von Drittanbieterrisiken; fehlt sie, entdeckt die Organisation Änderungen erst über das Fehlverhalten des Systems und kann Pflichten wie die Vorfallmeldung an den Anbieter (AI Act Art. 26 Abs. 5) nicht fristgerecht erfüllen.', 'Risk of non-compliance: Without ongoing monitoring of AI suppliers, model swaps, changed terms of use, security incidents at the vendor and discontinuations go unnoticed until they take effect in the organisation''s own operations. MANAGE 3.1 requires regular monitoring and treatment of third-party risks; without it the organisation discovers changes only through system misbehaviour and cannot meet duties such as incident notification to the provider (AI Act Art. 26(5)) on time.', 'NIST_AI_RMF'),
  ('DR-NAIRMF-Ma4.1', 'Delta-Pack', 'Risiko bei Nichterfüllung: Ohne Betriebsüberwachung auf Drift und Vorfälle merkt die Organisation Leistungsabfälle erst an Beschwerden, Umsatzeinbrüchen oder Presseberichten – Wochen nach Beginn des Problems. MANAGE 4.1 verlangt Post-Deployment-Monitoring mit definierten Reaktionsprozessen; fehlt es, ist für Hochrisiko-Systeme die Nachbetriebsbeobachtung nach AI Act Art. 72 nicht erfüllt, und Vorfallmeldungen nach Art. 73 kommen systematisch zu spät.', 'Risk of non-compliance: Without operational monitoring for drift and incidents, the organisation notices performance decline only through complaints, revenue drops or press reports – weeks after the problem began. MANAGE 4.1 requires post-deployment monitoring with defined response processes; without it, post-market monitoring under AI Act Art. 72 is unmet for high-risk systems, and incident reports under Art. 73 are systematically late.', 'NIST_AI_RMF'),
  ('DR-NAIRMF-Ma4.3', 'Delta-Pack', 'Risiko bei Nichterfüllung: Werden Vorfälle und Beinahe-Vorfälle nicht dokumentiert, fehlt die Datenbasis für Muster („dritter Prompt-Injection-Versuch in diesem Monat“), und dieselbe Schwachstelle bleibt nach ihrer ersten Entdeckung ungesichert. MANAGE 4.3 verlangt die Dokumentation und Kommunikation von Vorfällen und Fehlern; ohne Aufzeichnung kann die Organisation bei einer Behördenanfrage weder Vorfallhistorie noch Lernprozess vorlegen, was als fehlende Nachweisbarkeit des gesamten Risikomanagements gewertet wird.', 'Risk of non-compliance: If incidents and near misses are not documented, there is no data basis for patterns (''third prompt-injection attempt this month''), and the same weakness stays unsecured after its first discovery. MANAGE 4.3 requires documentation and communication of incidents and errors; without records the organisation can present neither incident history nor learning process when an authority asks, which is treated as a lack of accountability for the entire risk management.', 'NIST_AI_RMF'),
  ('DR-NAIRMF-Me1.1', 'Delta-Pack', 'Risiko bei Nichterfüllung: Ohne geeignete Metriken werden die Risiken gemessen, die leicht messbar sind (Latenz, Verfügbarkeit), nicht die, die schaden (Fehlerraten je Subgruppe, Halluzinationsquote, Erklärbarkeit) – das Dashboard ist grün, während das System diskriminiert. MEASURE 1.1 verlangt die Auswahl von Methoden und Metriken für die identifizierten Risiken und die Dokumentation nicht messbarer Risiken; fehlt sie, sind alle nachfolgenden Messungen aussagelos und als Nachweis wertlos.', 'Risk of non-compliance: Without suitable metrics, the risks measured are those easy to measure (latency, availability), not those that cause harm (error rates per subgroup, hallucination rate, explainability) – the dashboard is green while the system discriminates. MEASURE 1.1 requires selecting methods and metrics for the identified risks and documenting risks that cannot be measured; without this, all subsequent measurements are meaningless and worthless as evidence.', 'NIST_AI_RMF'),
  ('DR-NAIRMF-Me2.1', 'Delta-Pack', 'Risiko bei Nichterfüllung: Ohne dokumentierte Tests auf Gültigkeit und Zuverlässigkeit weiß niemand, ob das Modell unter Produktionsbedingungen konsistent das misst, was es messen soll; Testergebnisse aus der Entwicklung werden als Betriebsgarantie missverstanden. MEASURE 2.1 und 2.5 verlangen Testdokumentation und den Nachweis der Validität für den Einsatzkontext; fehlt sie, kann die Genauigkeitsanforderung des AI Act Art. 15 nicht belegt werden, und Fehlentscheidungen gelten als vorhersehbar.', 'Risk of non-compliance: Without documented validity and reliability tests nobody knows whether the model consistently measures what it is supposed to under production conditions; development test results are mistaken for an operational guarantee. MEASURE 2.1 and 2.5 require test documentation and proof of validity for the deployment context; without it, the accuracy requirement of AI Act Art. 15 cannot be evidenced and wrong decisions count as foreseeable.', 'NIST_AI_RMF'),
  ('DR-NAIRMF-Me2.5', 'Delta-Pack', 'Risiko bei Nichterfüllung: Werden Fairness, Erklärbarkeit und Robustheit nicht gemessen, bleiben Ungleichbehandlung, unerklärbare Ablehnungen und Anfälligkeit für Störeingaben unbekannte Größen – bis Betroffene, Auditoren oder Angreifer sie finden. MEASURE 2.5/2.9/2.11 verlangen die Messung dieser Merkmale mit dokumentierten Ergebnissen; ohne sie sind die Anforderungen des AI Act aus Art. 10 (Bias), Art. 13 (Transparenz) und Art. 15 (Robustheit) nicht belegbar, und AGG-Klagen treffen ein Unternehmen ohne Entlastungsbeweis.', 'Risk of non-compliance: If fairness, explainability and robustness are not measured, unequal treatment, inexplicable rejections and susceptibility to perturbed inputs remain unknown quantities – until affected persons, auditors or attackers find them. MEASURE 2.5/2.9/2.11 require measuring these characteristics with documented results; without them the AI Act requirements of Art. 10 (bias), Art. 13 (transparency) and Art. 15 (robustness) cannot be evidenced, and equal-treatment claims hit a company with no exculpatory proof.', 'NIST_AI_RMF'),
  ('DR-NAIRMF-Me2.7', 'Delta-Pack', 'Risiko bei Nichterfüllung: Ohne Sicherheits- und Resilienzprüfung (einschließlich adversarialer Tests) bleiben Angriffsflächen wie Prompt Injection, Modellextraktion und Datenvergiftung unentdeckt; das System fällt beim ersten gezielten Angriff aus oder gibt vertrauliche Daten preis. MEASURE 2.7 verlangt die Prüfung und Dokumentation von Sicherheit und Resilienz; fehlt sie, ist AI Act Art. 15 Abs. 5 nicht erfüllt, und ein erfolgreicher Angriff löst parallel DSGVO- und NIS2-Meldepflichten aus, auf die niemand vorbereitet ist.', 'Risk of non-compliance: Without security and resilience testing (including adversarial tests), attack surfaces such as prompt injection, model extraction and data poisoning remain undiscovered; the system fails at the first targeted attack or discloses confidential data. MEASURE 2.7 requires testing and documenting security and resilience; without it, AI Act Art. 15(5) is unmet, and a successful attack triggers GDPR and NIS2 reporting duties in parallel for which nobody is prepared.', 'NIST_AI_RMF'),
  ('DR-NAIRMF-Me3.1', 'Delta-Pack', 'Risiko bei Nichterfüllung: Ohne Mechanismus zur Nachverfolgung identifizierter Risiken werden Befunde aus Bewertungen einmal notiert und nie wieder geprüft; ob ein Risiko gemindert, gewachsen oder durch ein Update neu entstanden ist, weiß niemand. MEASURE 3.1 verlangt Verfahren zur Verfolgung von Risiken über den Lebenszyklus; fehlt es, verliert das Risikomanagement seine Iterationsfähigkeit (auch nach AI Act Art. 9 Abs. 2 gefordert), und Auditoren finden ein Risikoregister ohne Statusänderung seit seiner Erstellung.', 'Risk of non-compliance: Without a mechanism for tracking identified risks, findings from assessments are noted once and never revisited; whether a risk has been mitigated, has grown or has re-emerged through an update, nobody knows. MEASURE 3.1 requires procedures for tracking risks over the lifecycle; without it, risk management loses its iterative capability (also required by AI Act Art. 9(2)), and auditors find a risk register with no status change since creation.', 'NIST_AI_RMF'),
  ('DR-NAIRMF-Me4.1', 'Delta-Pack', 'Risiko bei Nichterfüllung: Ohne Rückkopplung aus dem Betrieb (Nutzerbeschwerden, Override-Quoten, Supportanfragen) wird die Wirksamkeit der Maßnahmen nie an der Realität geprüft – gemessen wird, was vor dem Go-live geplant war, nicht, was tatsächlich schiefgeht. MEASURE 4.1/4.2 verlangen die Nutzung von Betriebsfeedback und die Bewertung der Messmethoden im Einsatzkontext; ohne dies bleiben Wirksamkeitsnachweise theoretisch, und die Organisation kann nicht belegen, dass ihre Kontrollen in der Praxis greifen.', 'Risk of non-compliance: Without feedback from operations (user complaints, override rates, support tickets), the effectiveness of measures is never checked against reality – what gets measured is what was planned before go-live, not what actually goes wrong. MEASURE 4.1/4.2 require using operational feedback and evaluating measurement methods in the deployment context; without this, effectiveness evidence stays theoretical and the organisation cannot show that its controls work in practice.', 'NIST_AI_RMF')
