-- ============================================================================
-- Hochwertige, einzeln verfasste Risikotexte (Fable) für 130 bestehende
-- KI-Kontrollen — ersetzt die maschinellen Echo-Texte. Idempotent (UPSERT).
-- ============================================================================
BEGIN;

ON CONFLICT (risk_id) DO UPDATE
  SET text_de = EXCLUDED.text_de, text_en = EXCLUDED.text_en;

-- sicherstellen, dass jede Kontrolle mit ihrem DR-Risiko verknüpft ist
ON CONFLICT (framework, control_id, risk_id) DO NOTHING;

COMMIT;
